"  -w FLAG  adjust warnings (use '-w list' to list warnings)\n",
          kNinjaVersion,
          (int)GetParallelism());
}

int main(int argc, char* argv[]) {
  NinjaOptions opts;
  opts.input_file = "build.ninja";
  opts.parallelism = GetParallelism();
  opts.failures_allowed = 1;

  // Parse top-level arguments
  int i = 1;
  const char* tool_name = nullptr;
  std::vector<const char*> tool_args;

  for (; i < argc; ++i) {
    const char* arg = argv[i];

    if (strcmp(arg, "--version") == 0) {
      printf("%s\n", kNinjaVersion);
      return 0;
    } else if (strcmp(arg, "-v") == 0 || strcmp(arg, "--verbose") == 0) {
      opts.verbose = true;
    } else if (strcmp(arg, "--quiet") == 0) {
      opts.quiet = true;
    } else if (strcmp(arg, "-n") == 0) {
      opts.dry_run = true;
    } else if (strcmp(arg, "-C") == 0) {
      if (i + 1 >= argc) {
        fprintf(stderr, "ninja: error: -C requires an argument\n");
        return 1;
      }
      opts.dir = argv[++i];
    } else if (strncmp(arg, "-C", 2) == 0) {
      opts.dir = arg + 2;
    } else if (strcmp(arg, "-f") == 0) {
      if (i + 1 >= argc) {
        fprintf(stderr, "ninja: error: -f requires an argument\n");
        return 1;
      }
      opts.input_file = argv[++i];
    } else if (strncmp(arg, "-f", 2) == 0) {
      opts.input_file = arg + 2;
    } else if (strcmp(arg, "-j") == 0) {
      if (i + 1 >= argc) {
        fprintf(stderr, "ninja: error: -j requires an argument\n");
        return 1;
      }
      opts.parallelism = atoi(argv[++i]);
      if (opts.parallelism < 0) {
        fprintf(stderr, "ninja: error: invalid -j parameter\n");
        return 1;
      }
    } else if (strncmp(arg, "-j", 2) == 0) {
      opts.parallelism = atoi(arg + 2);
    } else if (strcmp(arg, "-k") == 0) {
      if (i + 1 >= argc) {
        fprintf(stderr, "ninja: error: -k requires an argument\n");
        return 1;
      }
      opts.failures_allowed = atoi(argv[++i]);
    } else if (strncmp(arg, "-k", 2) == 0) {
      opts.failures_allowed = atoi(arg + 2);
    } else if (strcmp(arg, "-l") == 0) {
      if (i + 1 >= argc) {
        fprintf(stderr, "ninja: error: -l requires an argument\n");
        return 1;
      }
      opts.max_load_average = atof(argv[++i]);
    } else if (strncmp(arg, "-l", 2) == 0) {
      opts.max_load_average = atof(arg + 2);
    } else if (strcmp(arg, "-d") == 0) {
      if (i + 1 >= argc) {
        fprintf(stderr, "ninja: error: -d requires an argument\n");
        return 1;
      }
      const char* mode = argv[++i];
      if (!opts.SetDebugMode(mode)) {
        return 1;
      }
    } else if (strncmp(arg, "-d", 2) == 0) {
      if (!opts.SetDebugMode(arg + 2)) {
        return 1;
      }
    } else if (strcmp(arg, "-t") == 0) {
      if (i + 1 >= argc) {
        fprintf(stderr, "ninja: error: -t requires an argument\n");
        return 1;
      }
      tool_name = argv[++i];
      // rest of args go to tool
      for (++i; i < argc; ++i)
        tool_args.push_back(argv[i]);
      break;
    } else if (strncmp(arg, "-t", 2) == 0) {
      tool_name = arg + 2;
      for (++i; i < argc; ++i)
        tool_args.push_back(argv[i]);
      break;
    } else if (strcmp(arg, "-w") == 0) {
      if (i + 1 >= argc) {
        fprintf(stderr, "ninja: error: -w requires an argument\n");
        return 1;
      }
      if (!opts.SetWarningMode(argv[++i])) {
        return 1;
      }
    } else if (strncmp(arg, "-w", 2) == 0) {
      if (!opts.SetWarningMode(arg + 2)) {
        return 1;
      }
    } else if (arg[0] == '-') {
      fprintf(stderr, "ninja: error: unknown flag '%s'\n", arg);
      Usage();
      return 1;
    } else {
      // Target
      opts.targets.push_back(arg);
    }
  }

  // Change directory if -C was specified
  if (!opts.dir.empty()) {
    if (chdir(opts.dir.c_str()) < 0) {
      fprintf(stderr, "ninja: error: chdir('%s') - %s\n",
              opts.dir.c_str(), strerror(errno));
      return 1;
    }
  }

  // Handle -t tool
  if (tool_name) {
    // Load the build file (most tools need it)
    State state;
    ManifestParser parser(&state, opts);
    std::string err;
    if (!parser.Load(opts.input_file, &err)) {
      fprintf(stderr, "ninja: error: %s\n", err.c_str());
      if (strcmp(tool_name, "list") != 0)
        return 1;
      return RunTool(tool_name, tool_args, nullptr, opts);
    }
    return RunTool(tool_name, tool_args, &state, opts);
  }

  // Normal build
  return RunBuild(opts);
}
