#include "util.h"
#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/time.h>
#include <algorithm>
#include <map>

// CPU count
int GetParallelism() {
  int count = (int)sysconf(_SC_NPROCESSORS_ONLN);
  if (count < 1) count = 1;
  // match ninja's behavior: parallelism = cpu_count + 2
  return count + 2;
}

std::string StringPrintf(const char* fmt, ...) {
  char buf[4096];
  va_list ap;
  va_start(ap, fmt);
  vsnprintf(buf, sizeof(buf), fmt, ap);
  va_end(ap);
  return std::string(buf);
}

void Fatal(const char* msg, ...) {
  va_list ap;
  fprintf(stderr, "ninja: fatal: ");
  va_start(ap, msg);
  vfprintf(stderr, msg, ap);
  va_end(ap);
  fprintf(stderr, "\n");
  exit(1);
}

void Warning(const char* msg, ...) {
  va_list ap;
  fprintf(stderr, "ninja: warning: ");
  va_start(ap, msg);
  vfprintf(stderr, msg, ap);
  va_end(ap);
  fprintf(stderr, "\n");
}

void Error(const char* msg, ...) {
  va_list ap;
  fprintf(stderr, "ninja: error: ");
  va_start(ap, msg);
  vfprintf(stderr, msg, ap);
  va_end(ap);
  fprintf(stderr, "\n");
}

std::string EscapeForShell(const std::string& s) {
  // Simple shell escaping
  bool needs_quote = false;
  for (char c : s) {
    if (c == ' ' || c == '\t' || c == '$' || c == '\\' || c == '\'') {
      needs_quote = true;
      break;
    }
  }
  if (!needs_quote) return s;
  std::string result = "'";
  for (char c : s) {
    if (c == '\'') result += "'\\''";
    else result += c;
  }
  result += "'";
  return result;
}

uint64_t HashCommand(const std::string& command) {
  // FNV-1a hash
  uint64_t h = 14695981039346656037ULL;
  for (char c : command) {
    h ^= (uint64_t)(unsigned char)c;
    h *= 1099511628211ULL;
  }
  return h;
}

bool ReadFile(const std::string& path, std::string* contents, std::string* err) {
  FILE* f = fopen(path.c_str(), "rb");
  if (!f) {
    *err = strerror(errno);
    return false;
  }
  char buf[65536];
  size_t n;
  while ((n = fread(buf, 1, sizeof(buf), f)) > 0) {
    contents->append(buf, n);
  }
  bool ok = !ferror(f);
  fclose(f);
  if (!ok) {
    *err = strerror(errno);
    return false;
  }
  return true;
}

int64_t GetTimeMillis() {
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (int64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

uint64_t GetTimeNanos() {
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;
}

// Path canonicalization
static bool IsSlash(char c) {
  return c == '/';
}

std::string CanonicalizePath(const std::string& path) {
  std::string result = path;
  uint64_t slash_bits = 0;
  std::string err;
  CanonicalizePath(&result, &slash_bits, &err);
  return result;
}

bool CanonicalizePath(std::string* path, uint64_t* slash_bits, std::string* err) {
  // Simplified canonicalization
  if (path->empty()) return true;

  std::string& s = *path;

  // Process path components
  std::vector<std::string> parts;
  bool absolute = !s.empty() && s[0] == '/';

  size_t start = 0;
  for (size_t i = 0; i <= s.size(); i++) {
    if (i == s.size() || s[i] == '/') {
      if (i > start) {
        std::string part = s.substr(start, i - start);
        if (part == ".") {
          // skip
        } else if (part == "..") {
          if (!parts.empty() && parts.back() != "..") {
            parts.pop_back();
          } else if (!absolute) {
            parts.push_back("..");
          }
        } else {
          parts.push_back(part);
        }
      }
      start = i + 1;
    }
  }

  std::string result;
  if (absolute) result = "/";
  for (size_t i = 0; i < parts.size(); i++) {
    if (i > 0) result += "/";
    result += parts[i];
  }
  if (result.empty() && !absolute) result = ".";

  *path = result;
  if (slash_bits) *slash_bits = 0;
  return true;
}

// Metrics
struct MetricEntry {
  int64_t count;
  int64_t total_us;
  int64_t start_time;
};

static std::map<std::string, MetricEntry> g_metrics;
static bool g_collect_metrics = false;

void EnableMetrics() {
  g_collect_metrics = true;
}

ScopedMetric::ScopedMetric(const char* name) : name_(name) {
  if (!g_collect_metrics) {
    start_time_ = 0;
    return;
  }
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  start_time_ = (int64_t)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
}

ScopedMetric::~ScopedMetric() {
  if (!g_collect_metrics || !start_time_) return;
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  int64_t end_time = (int64_t)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
  auto& e = g_metrics[name_];
  e.count++;
  e.total_us += (end_time - start_time_);
}

void MetricRecord(const char* name, int64_t count) {
  if (!g_collect_metrics) return;
  auto& e = g_metrics[name];
  e.count += count;
}

void PrintMetrics() {
  if (!g_collect_metrics) return;
  printf("%-20s\t%-6s\t%-9s\t%s\n", "metric", "count", "avg (us)", "total (ms)");
  for (auto& kv : g_metrics) {
    double avg = kv.second.count > 0 ? (double)kv.second.total_us / kv.second.count : 0;
    double total_ms = kv.second.total_us / 1000.0;
    printf("%-20s\t%-6lld\t%-9.1f\t%.1f\n",
           kv.first.c_str(),
           (long long)kv.second.count,
           avg,
           total_ms);
  }
}

bool AreMetricsEnabled() {
  return g_collect_metrics;
}

SpeedMeter::SpeedMeter(int n) : n_(n < 16 ? n : 16), last_slot_(-1), initialized_(false) {
  memset(times_, 0, sizeof(times_));
  memset(counts_, 0, sizeof(counts_));
}

void SpeedMeter::Record(int count) {
  int64_t now = GetTimeMillis();
  // Find appropriate slot
  int slot = (int)(now / 1000) % n_;
  if (slot != last_slot_) {
    last_slot_ = slot;
    times_[slot] = now;
    counts_[slot] = 0;
    initialized_ = true;
  }
  counts_[slot] += count;
}

double SpeedMeter::rate() const {
  if (!initialized_) return 0;
  int64_t now = GetTimeMillis();
  int64_t oldest = now;
  int total = 0;
  for (int i = 0; i < n_; i++) {
    if (times_[i] > 0 && times_[i] < oldest)
      oldest = times_[i];
    total += counts_[i];
  }
  int64_t elapsed = now - oldest;
  if (elapsed < 1) return 0;
  return (double)total / (elapsed / 1000.0);
}

double SpeedMeter::Predict(int count, int64_t now) const {
  double r = rate();
  if (r < 0.0001) return -1;
  return count / r;
}
