#pragma once
#include <string>
#include <vector>
#include <map>

// An EvalString is a string that can contain variable references
// It's stored as a list of (string, is_special) pairs
// where is_special means it's a variable reference
struct EvalString {
  void AddText(const std::string& text) {
    if (!text.empty())
      parts_.push_back({text, false});
  }
  void AddSpecial(const std::string& var) {
    parts_.push_back({var, true});
  }

  bool empty() const { return parts_.empty(); }

  struct Part {
    std::string text;
    bool is_special;
  };
  std::vector<Part> parts_;

  std::string Serialize() const;
  std::string Unparse() const;
};

// An environment for variable lookup
struct Env {
  virtual ~Env() {}
  virtual std::string LookupVariable(const std::string& var) = 0;
};

// A scope/binding environment
struct BindingEnv : public Env {
  BindingEnv() : parent_(nullptr) {}
  explicit BindingEnv(BindingEnv* parent) : parent_(parent) {}

  virtual std::string LookupVariable(const std::string& var) override;

  void AddBinding(const std::string& key, const std::string& val) {
    bindings_[key] = val;
  }

  std::string LookupWithFallback(const std::string& var, const EvalString* eval, Env* env);

  std::map<std::string, std::string> bindings_;
  BindingEnv* parent_;
};

// Evaluate an EvalString in a given environment
std::string EvalStringEvaluate(const EvalString& str, Env* env);
