  for (const auto& part : parts_) {
    if (part.is_special) {
      result += "${" + part.text + "}";
    } else {
      // Escape $ in text parts
      for (char c : part.text) {
        if (c == '$') result += "$$";
        else result += c;
      }
    }
  }
  return result;
}

