#pragma once
#include <string>
#include <vector>
#include <map>
#include <set>
#include <stdint.h>
#include "eval_env.h"

struct Node;
struct Edge;
struct Pool;
struct State;

// Node represents a file in the build graph
struct Node {
  explicit Node(const std::string& path, uint64_t slash_bits = 0)
      : path_(path), slash_bits_(slash_bits), 
        mtime_(-1), stat_unchecked_(true), exists_(false),
        in_edge_(nullptr), dirty_(false), dyndep_pending_(false),
        id_(-1) {}

  const std::string& path() const { return path_; }
  uint64_t slash_bits() const { return slash_bits_; }

  // File modification time, -1 if not yet stat'd, 0 if doesn't exist
  int64_t mtime() const { return mtime_; }
  bool exists() const { return exists_; }
  bool stat_unchecked() const { return stat_unchecked_; }

  // Returns true if stat succeeded
  bool Stat(std::string* err);
  bool StatIfPossible(std::string* err);
  void ResetState();

  // The edge that produces this node (may be null for source files)
  Edge* in_edge() const { return in_edge_; }
  void set_in_edge(Edge* edge) { in_edge_ = edge; }

  // Edges that consume this node
  std::vector<Edge*> out_edges_;
  std::vector<Edge*> validation_out_edges_;

  bool dirty() const { return dirty_; }
  void set_dirty(bool dirty) { dirty_ = dirty; }

  bool dyndep_pending() const { return dyndep_pending_; }
  void set_dyndep_pending(bool pending) { dyndep_pending_ = pending; }

  int id() const { return id_; }
  void set_id(int id) { id_ = id; }

  std::string path_;
  uint64_t slash_bits_;
  int64_t mtime_;
  bool stat_unchecked_;
  bool exists_;
  Edge* in_edge_;
  bool dirty_;
  bool dyndep_pending_;
  int id_;
};

// Rule represents a build rule
struct Rule {
  explicit Rule(const std::string& name) : name_(name) {}

  const std::string& name() const { return name_; }

  void AddBinding(const std::string& key, const EvalString& val) {
    bindings_[key] = val;
  }

  static bool IsReservedBinding(const std::string& var);

  const EvalString* GetBinding(const std::string& key) const {
    auto it = bindings_.find(key);
    if (it == bindings_.end()) return nullptr;
    return &it->second;
  }

  std::string name_;
  std::map<std::string, EvalString> bindings_;
};

// Pool represents a pool of execution slots
struct Pool {
  explicit Pool(const std::string& name, int depth) 
      : name_(name), depth_(depth), current_use_(0) {}

  bool is_valid() const { return depth_ > 0 || name_ == "console"; }
  int depth() const { return depth_; }
  const std::string& name() const { return name_; }

  void DelayEdge(Edge* edge) { delayed_.push_back(edge); }

  // Returns the next edge to run from the delayed list, or nullptr
  Edge* GetNextEdge();

  bool ShouldDelayEdge() const { return depth_ > 0 && current_use_ >= depth_; }

  void EdgeScheduled(const Edge& edge);
  void EdgeFinished(const Edge& edge);

  bool operator<(const Pool& other) const { return name_ < other.name_; }

  std::string name_;
  int depth_;
  int current_use_;
  std::vector<Edge*> delayed_;
};

// Edge represents a build statement
struct Edge {
  enum VisitMark { VISIT_NONE, VISIT_IN_STACK, VISIT_DONE };

  Edge() : rule_(nullptr), pool_(nullptr), env_(nullptr),
           mark_(VISIT_NONE), id_(0), outputs_ready_(false),
           deps_missing_(false), command_start_time_(0),
           implicit_deps_(0), order_only_deps_(0),
           implicit_outs_(0) {}

  bool AllInputsReady() const;

  // Evaluate a binding for this edge (looks up in rule, then env)
  std::string GetBinding(const std::string& key) const;
  bool GetBindingBool(const std::string& key) const;

  std::string EvaluateCommand(bool incl_rsp_file = false) const;
  std::string GetDescription() const;

  bool IsPhony() const;
  bool IsDirty() const;

  bool RecomputeOutputDirty(const std::string* /*unused*/,
                             int64_t deps_mtime, const std::string& /*unused*/,
                             Node* output, std::string* err);

  // Rule pointer
  const Rule* rule_;
  // Pool this edge uses
  Pool* pool_;
  // Environment for variable lookup
  BindingEnv* env_;

  std::vector<Node*> inputs_;
  std::vector<Node*> outputs_;
  std::vector<Node*> validations_;

  // Counts for partition of inputs
  int implicit_deps_;    // number of implicit deps (at end of inputs, before order_only)
  int order_only_deps_;  // number of order-only deps (at end of inputs)
  int implicit_outs_;    // number of implicit outputs (at end of outputs)

  VisitMark mark_;
  int id_;
  bool outputs_ready_;
  bool deps_missing_;
  int64_t command_start_time_;

  // Edge bindings (from build block)
  BindingEnv* edge_env_;

  std::string GetCommandLine() const;
};

// Dependency entry in deps log
struct DepsEntry {
  DepsEntry() : mtime(0) {}
  int64_t mtime;
  std::vector<Node*> nodes;
};
