bool Node::Stat(std::string* err) {
  struct stat st;
  stat_unchecked_ = false;
  if (stat(path_.c_str(), &st) < 0) {
    if (errno == ENOENT || errno == ENOTDIR) {
      mtime_ = 0;
      exists_ = false;
      return true;
    }
    *err = path_ + ": " + strerror(errno);
    return false;
  }
  exists_ = true;
  // Use nanosecond mtime
#ifdef __APPLE__
  mtime_ = (int64_t)st.st_mtimespec.tv_sec * 1000000000LL + st.st_mtimespec.tv_nsec;
#else
  mtime_ = (int64_t)st.st_mtim.tv_sec * 1000000000LL + st.st_mtim.tv_nsec;
#endif
  return true;
}

bool Node::StatIfPossible(std::string* err) {
  if (stat_unchecked_)
    return Stat(err);
  return true;
}

void Node::ResetState() {
  mtime_ = -1;
  stat_unchecked_ = true;
  exists_ = false;
  dirty_ = false;
}

bool Rule::IsReservedBinding(const std::string& var) {
  static const char* reserved[] = {
    "command", "depfile", "dyndep", "description", "deps",
    "generator", "pool", "restat", "rspfile", "rspfile_content",
    "msvc_deps_prefix", nullptr
  };
  for (int i = 0; reserved[i]; i++) {
    if (var == reserved[i]) return true;
  }
  return false;
}

// Edge implementation
std::string Edge::GetBinding(const std::string& key) const {
  if (env_) {
    // Check edge-level bindings first
    auto it = env_->bindings_.find(key);
    if (it != env_->bindings_.end())
      return it->second;
  }

  // Check rule bindings with proper evaluation
  if (rule_) {
    const EvalString* binding = rule_->GetBinding(key);
    if (binding) {
      // Evaluate in the edge's environment
      if (env_) return EvalStringEvaluate(*binding, env_);
      BindingEnv empty;
      return EvalStringEvaluate(*binding, &empty);
    }
  }

  // Fall back to parent env
  if (env_ && env_->parent_) {
    return env_->parent_->LookupVariable(key);
  }
  return "";
}

bool Edge::GetBindingBool(const std::string& key) const {
  return !GetBinding(key).empty();
}

bool Edge::IsPhony() const {
  return rule_->name() == "phony";
}

std::string Edge::EvaluateCommand(bool incl_rsp_file) const {
  std::string cmd = GetBinding("command");
  if (incl_rsp_file) {
    std::string rspfile = GetBinding("rspfile");
    std::string content = GetBinding("rspfile_content");
    if (!rspfile.empty() && !content.empty()) {
      // Replace @rspfile with content in command
      std::string at_rsp = "@" + rspfile;
      size_t pos = 0;
      while ((pos = cmd.find(at_rsp, pos)) != std::string::npos) {
        cmd.replace(pos, at_rsp.size(), content);
        pos += content.size();
      }
    }
  }
  return cmd;
}

std::string Edge::GetDescription() const {
  std::string desc = GetBinding("description");
  if (desc.empty()) return GetBinding("command");
  return desc;
}

Pool::~Pool() {}

void Pool::EdgeScheduled(const Edge& edge) {
  if (depth_ > 0) current_use_++;
}

void Pool::EdgeFinished(const Edge& edge) {
  if (depth_ > 0) current_use_--;
}

Edge* Pool::GetNextEdge() {
  if (delayed_.empty()) return nullptr;
  Edge* e = delayed_.front();
  delayed_.erase(delayed_.begin());
  return e;
}
