struct Lexer {
  Lexer() {}
  explicit Lexer(const std::string& filename, const std::string& input, int line_offset = 0);

  enum Token {
    ERROR, BUILD, COLON, DEFAULT, EQUALS, IDENT, INCLUDE, INDENT, NEWLINE,
    PIPE, PIPE2, PIPEAT, POOL, RULE, SUBNINJA, TEOF
  };

  // Returns the next token
  Token ReadToken();

  // After a token is read, returns its value (for IDENT)
  bool ReadIdent(std::string* out);

  // Read a path (with variable expansion markers)
  bool ReadPath(EvalString* path, std::string* err);

  // Read a variable value (right side of =)  
  bool ReadVarValue(EvalString* out, std::string* err);

  // Error reporting
  bool Error(const std::string& msg, std::string* err);

  std::string filename_;
  const char* input_begin_;
  const char* input_end_;
  const char* p_;  // current position
  const char* last_token_;
  int line_number_;
  int line_offset_;

  void AdvanceToNewline();
  bool ReadEvalString(EvalString* out, bool path, std::string* err);
};

