#include "lexer.h"
#include <string.h>
#include <stdio.h>
#include <assert.h>

Lexer::Lexer(const std::string& filename, const std::string& input, int line_offset)
    : filename_(filename), line_number_(1 + line_offset), line_offset_(line_offset) {
  // We keep a copy of the input in the buffer
  // For now, just set up pointers
  // NOTE: The Lexer doesn't own the input string - caller must keep it alive
  // We store the string in a local variable
  input_begin_ = input.data();
  input_end_ = input.data() + input.size();
  p_ = input_begin_;
  last_token_ = p_;
}

const char* TokenName(Lexer::Token t) {
  switch (t) {
    case Lexer::ERROR: return "error token";
    case Lexer::BUILD: return "'build'";
    case Lexer::COLON: return "':'";
    case Lexer::DEFAULT: return "'default'";
    case Lexer::EQUALS: return "'='";
    case Lexer::IDENT: return "identifier";
    case Lexer::INCLUDE: return "'include'";
    case Lexer::INDENT: return "indent";
    case Lexer::NEWLINE: return "newline";
    case Lexer::PIPE: return "'|'";
    case Lexer::PIPE2: return "'||'";
    case Lexer::PIPEAT: return "'|@'";
    case Lexer::POOL: return "'pool'";
    case Lexer::RULE: return "'rule'";
    case Lexer::SUBNINJA: return "'subninja'";
    case Lexer::TEOF: return "eof";
  }
  return "unknown token";
}

bool Lexer::Error(const std::string& msg, std::string* err) {
  // Find the current line content for error reporting
  const char* line_start = last_token_;
  while (line_start > input_begin_ && *(line_start - 1) != '\n')
    --line_start;
  const char* line_end = last_token_;
  while (line_end < input_end_ && *line_end != '\n')
    ++line_end;

  int col = (int)(last_token_ - line_start);

  char buf[4096];
  snprintf(buf, sizeof(buf), "%s:%d: %s\n", 
           filename_.c_str(), line_number_, msg.c_str());
  *err = buf;

  // Add the context line
  std::string line(line_start, line_end);
  *err += line + "\n";
  *err += std::string(col, ' ') + "^ near here";

  return false;
}

// Skip whitespace (spaces and tabs) but not newlines
static void SkipWhitespace(const char*& p) {
  while (*p == ' ' || *p == '\t') ++p;
}

// Check if character is valid in an identifier
static bool IsIdentChar(char c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || 
         (c >= '0' && c <= '9') || c == '_' || c == '-' || c == '.';
}

Lexer::Token Lexer::ReadToken() {
  const char* p = p_;

  for (;;) {
    last_token_ = p;

    if (p >= input_end_) {
      p_ = p;
      return TEOF;
    }

    char c = *p;

    // Skip comments
    if (c == '#') {
      while (p < input_end_ && *p != '\n') ++p;
      continue;
    }

    // Handle newlines
    if (c == '\n') {
      ++p;
      ++line_number_;
      last_token_ = p;
      p_ = p;
      return NEWLINE;
    }

    if (c == '\r') {
      ++p;
      if (p < input_end_ && *p == '\n') {
        ++p;
        ++line_number_;
      }
      last_token_ = p;
      p_ = p;
      return NEWLINE;
    }

    // Skip whitespace at start of line = INDENT
    if ((p == input_begin_ || *(p-1) == '\n') && (c == ' ' || c == '\t')) {
      while (p < input_end_ && (*p == ' ' || *p == '\t')) ++p;
      p_ = p;
      return INDENT;
    }

    // Skip spaces/tabs
    if (c == ' ' || c == '\t') {
      ++p;
      continue;
    }

    if (c == '=') {
      ++p;
      p_ = p;
      return EQUALS;
    }

    if (c == ':') {
      ++p;
      p_ = p;
      return COLON;
    }

    if (c == '|') {
      ++p;
      if (p < input_end_ && *p == '|') {
        ++p;
        p_ = p;
        return PIPE2;
      } else if (p < input_end_ && *p == '@') {
        ++p;
        p_ = p;
        return PIPEAT;
      }
      p_ = p;
      return PIPE;
    }

    // Identifiers and keywords
    if (IsIdentChar(c) || c == '/') {
      const char* start = p;
      while (p < input_end_ && IsIdentChar(*p)) ++p;

      std::string word(start, p);
      p_ = p;

      if (word == "build") return BUILD;
      if (word == "rule") return RULE;
      if (word == "default") return DEFAULT;
      if (word == "pool") return POOL;
      if (word == "include") return INCLUDE;
      if (word == "subninja") return SUBNINJA;
      return IDENT;
    }

    // Unknown character
    ++p;
    p_ = p;
    return ERROR;
  }
}

bool Lexer::ReadIdent(std::string* out) {
  const char* p = p_;
  SkipWhitespace(p);

  if (p >= input_end_) return false;

  const char* start = p;
  while (p < input_end_ && IsIdentChar(*p)) ++p;

  if (p == start) return false;

  *out = std::string(start, p);
  p_ = p;
  last_token_ = start;
  return true;
}

bool Lexer::ReadEvalString(EvalString* out, bool path, std::string* err) {
  const char* p = p_;
  std::string current;

  for (;;) {
    if (p >= input_end_) {
      out->AddText(current);
      p_ = p;
      return true;
    }

    char c = *p;

    if (c == '\n' || c == '\r') {
      // End of line
      out->AddText(current);
      p_ = p;
      return true;
    }

    if (path && (c == ' ' || c == '\t' || c == ':' || c == '|' || c == '\0')) {
      out->AddText(current);
      p_ = p;
      return true;
    }

    if (c == '$') {
      out->AddText(current);
      current.clear();
      ++p;

      if (p >= input_end_) {
        return Error("unexpected EOF after $", err);
      }

      char next = *p;

      if (next == '\n') {
        // Line continuation
        ++p;
        ++line_number_;
        // Skip leading whitespace on next line
        while (p < input_end_ && (*p == ' ' || *p == '\t')) ++p;
        continue;
      } else if (next == '\r') {
        ++p;
        if (p < input_end_ && *p == '\n') ++p;
        ++line_number_;
        while (p < input_end_ && (*p == ' ' || *p == '\t')) ++p;
        continue;
      } else if (next == '$') {
        current += '$';
        ++p;
      } else if (next == ' ') {
        current += ' ';
