  const char* p = p_;
  std::string current;

  for (;;) {
    if (p >= input_end_) {
      out->AddText(current);
      p_ = p;
      return true;
    }

    char c = *p;

    if (c == '\n' || c == '\r') {
      // End of line
      out->AddText(current);
      p_ = p;
      return true;
    }

    if (path && (c == ' ' || c == '\t' || c == ':' || c == '|' || c == '\0')) {
      out->AddText(current);
      p_ = p;
      return true;
    }

    if (c == '$') {
      out->AddText(current);
      current.clear();
      ++p;

      if (p >= input_end_) {
        return Error("unexpected EOF after $", err);
      }

      char next = *p;

      if (next == '\n') {
        // Line continuation
        ++p;
        ++line_number_;
        // Skip leading whitespace on next line
        while (p < input_end_ && (*p == ' ' || *p == '\t')) ++p;
        continue;
      } else if (next == '\r') {
        ++p;
        if (p < input_end_ && *p == '\n') ++p;
        ++line_number_;
        while (p < input_end_ && (*p == ' ' || *p == '\t')) ++p;
        continue;
      } else if (next == '$') {
        current += '$';
        ++p;
      } else if (next == ' ') {
        current += ' ';
        ++p;
      } else if (next == ':') {
        current += ':';
        ++p;
      } else if (next == '{') {
        // ${varname}
        ++p;
        const char* var_start = p;
        while (p < input_end_ && *p != '}') ++p;
        if (p >= input_end_) {
          return Error("expected } after ${", err);
        }
        std::string var(var_start, p);
        ++p;  // skip }
        out->AddSpecial(var);
      } else if (IsIdentChar(next)) {
        // $varname
        const char* var_start = p;
        while (p < input_end_ && IsIdentChar(*p)) ++p;
        std::string var(var_start, p);
        out->AddSpecial(var);
      } else {
        return Error(std::string("bad $-escape (literal $, $$, $: or ${, or $") + 
                     std::string(1, next) + ")", err);
      }
    } else {
      current += c;
      ++p;
    }
  }
}

bool Lexer::ReadPath(EvalString* path, std::string* err) {
  // Skip leading whitespace
  while (p_ < input_end_ && (*p_ == ' ' || *p_ == '\t')) ++p_;
  last_token_ = p_;
  return ReadEvalString(path, true, err);
}

bool Lexer::ReadVarValue(EvalString* out, std::string* err) {
  // Skip whitespace after =
  while (p_ < input_end_ && (*p_ == ' ' || *p_ == '\t')) ++p_;
  last_token_ = p_;
  return ReadEvalString(out, false, err);
}

void Lexer::AdvanceToNewline() {
  while (p_ < input_end_ && *p_ != '\n' && *p_ != '\r') ++p_;
}
