#include "manifest_parser.h"
#include "ninja.h"
#include "util.h"
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <algorithm>
#include <set>

ManifestParser::ManifestParser(State* state, const NinjaOptions& opts) : state_(state) {
  env_ = state->bindings_;
  options_.dupe_edge_action_ = kDupeEdgeActionWarn;
  options_.phony_cycle_action_ = opts.phony_cycle_action;
}

ManifestParser::ManifestParser(State* state, const ManifestParserOptions& opts) 
    : state_(state), options_(opts) {
  env_ = state->bindings_;
}

bool ManifestParser::Load(const std::string& filename, std::string* err, const Lexer* parent) {
  std::string contents;
  std::string read_err;
  if (!ReadFile(filename, &contents, &read_err)) {
    *err = "loading '" + filename + "': " + read_err;
    return false;
  }
  contents += "\n";  // Make sure file ends with newline
  return Parse(filename, contents, err);
}

bool ManifestParser::ParseTest(const std::string& input, std::string* err) {
  return Parse("input", input + "\n", err);
}

bool ManifestParser::Parse(const std::string& filename, const std::string& input, std::string* err) {
  input_storage_ = input;
  lexer_ = Lexer(filename, input_storage_);

  for (;;) {
    Lexer::Token token = lexer_.ReadToken();

    switch (token) {
      case Lexer::TEOF:
        return true;

      case Lexer::NEWLINE:
        continue;

      case Lexer::RULE:
        if (!ParseRule(err)) return false;
        break;

      case Lexer::BUILD:
        if (!ParseBuild(err)) return false;
        break;

      case Lexer::DEFAULT:
        if (!ParseDefault(err)) return false;
        break;

      case Lexer::POOL:
        if (!ParsePool(err)) return false;
        break;

      case Lexer::INCLUDE:
        if (!ParseFileInclude(false, err)) return false;
        break;

      case Lexer::SUBNINJA:
        if (!ParseFileInclude(true, err)) return false;
        break;

      case Lexer::IDENT: {
        // Variable assignment
        lexer_.p_ -= lexer_.p_ - lexer_.last_token_;  // backup to start of ident
        // Actually, ident was already consumed. Let's get it.
        std::string name(lexer_.last_token_, 
                         lexer_.p_);
        // Try reading = value
        if (!ParseVarDecl(err)) return false;
        break;
      }

      case Lexer::INDENT:
        // Top-level indented lines are errors, but let's be lenient
        // and skip them
        lexer_.AdvanceToNewline();
        break;

      default: {
        // Check if it's an ident we need to handle
        std::string msg = std::string("unexpected ") + TokenName(token);
        return lexer_.Error(msg, err);
      }
    }
  }
}

bool ManifestParser::ParseVarDecl(std::string* err) {
  // We already consumed the identifier token
  // Re-read it from last_token_
  std::string name(lexer_.last_token_, lexer_.p_);
  // Remove trailing whitespace
  while (!name.empty() && (name.back() == ' ' || name.back() == '\t'))
    name.pop_back();

  Lexer::Token token = lexer_.ReadToken();
  if (token != Lexer::EQUALS) {
    return lexer_.Error("expected = sign", err);
  }

  EvalString value;
  if (!lexer_.ReadVarValue(&value, err)) return false;

  // Skip to newline
  token = lexer_.ReadToken();
  if (token != Lexer::NEWLINE && token != Lexer::TEOF) {
    return lexer_.Error("expected newline, got " + std::string(TokenName(token)), err);
  }

  std::string evaluated = EvalStringEvaluate(value, env_);
  env_->AddBinding(name, evaluated);
  return true;
}

bool ManifestParser::ExpectToken(Lexer::Token expected, std::string* err) {
  Lexer::Token token = lexer_.ReadToken();
  if (token != expected) {
    std::string msg = std::string("expected ") + TokenName(expected) + 
                      ", got " + TokenName(token);
    return lexer_.Error(msg, err);
  }
  return true;
}

bool ManifestParser::ParseRule(std::string* err) {
  std::string name;
  if (!lexer_.ReadIdent(&name)) {
    return lexer_.Error("expected rule name", err);
  }

  if (!ExpectToken(Lexer::NEWLINE, err)) return false;

  if (state_->rules_.count(name)) {
    // Duplicate rule - it's allowed, later one wins (silently)
  }

  Rule* rule = new Rule(name);

  // Read indented bindings
  for (;;) {
    Lexer::Token token = lexer_.ReadToken();
    if (token == Lexer::NEWLINE) {
      continue;
    }
    if (token != Lexer::INDENT) {
      // Put back
      lexer_.p_ = lexer_.last_token_;
      break;
    }

    // Read key = value
    std::string key;
    if (!lexer_.ReadIdent(&key)) {
      return lexer_.Error("expected binding key", err);
    }

    if (!ExpectToken(Lexer::EQUALS, err)) return false;

    EvalString value;
    if (!lexer_.ReadVarValue(&value, err)) return false;

    if (!ExpectToken(Lexer::NEWLINE, err)) {
      // Try EOF
      if (lexer_.ReadToken() != Lexer::TEOF)
        return false;
    }

    rule->AddBinding(key, value);
  }

  if (!rule->GetBinding("command")) {
    delete rule;
    return lexer_.Error("expected 'command =' line", err);
  }

  state_->AddRule(rule);
  return true;
}

bool ManifestParser::ParseBuild(std::string* err) {
  std::vector<EvalString> outputs_raw;
  std::vector<EvalString> imp_outputs_raw;

  // Read outputs until ':'
  for (;;) {
    EvalString path;
    if (!lexer_.ReadPath(&path, err)) return false;
    if (path.empty()) break;
    outputs_raw.push_back(path);

    // Peek at next token
    const char* p = lexer_.p_;
    while (p < lexer_.input_end_ && (*p == ' ' || *p == '\t')) ++p;
    if (p < lexer_.input_end_ && *p == '|' && *(p+1) != '|' && *(p+1) != '@') {
      // implicit outputs
      lexer_.p_ = p + 1;
      for (;;) {
        EvalString imp_path;
        if (!lexer_.ReadPath(&imp_path, err)) return false;
        if (imp_path.empty()) break;
        imp_outputs_raw.push_back(imp_path);
      }
      break;
    }

    if (p < lexer_.input_end_ && *p == ':') break;
  }

  if (!ExpectToken(Lexer::COLON, err)) return false;

  std::string rule_name;
  if (!lexer_.ReadIdent(&rule_name)) {
    return lexer_.Error("expected build command name", err);
  }

  const Rule* rule = state_->LookupRule(rule_name);
  if (!rule) {
    return lexer_.Error("unknown build rule '" + rule_name + "'", err);
  }

  // Read explicit inputs
  std::vector<EvalString> inputs_raw;
  std::vector<EvalString> imp_inputs_raw;
  std::vector<EvalString> order_only_raw;
  std::vector<EvalString> validations_raw;

  int current_section = 0;  // 0=explicit, 1=implicit, 2=order-only, 3=validations

  for (;;) {
    // Check for | || |@
    const char* p = lexer_.p_;
    while (p < lexer_.input_end_ && (*p == ' ' || *p == '\t')) ++p;

    if (p >= lexer_.input_end_ || *p == '\n' || *p == '\r' || *p == '#') {
      break;
    }

    if (*p == '|') {
      if (*(p+1) == '|') {
        lexer_.p_ = p + 2;
        current_section = 2;
        continue;
      } else if (*(p+1) == '@') {
        lexer_.p_ = p + 2;
        current_section = 3;
        continue;
      } else {
        lexer_.p_ = p + 1;
        current_section = 1;
        continue;
      }
    }

    EvalString path;
    if (!lexer_.ReadPath(&path, err)) return false;
    if (path.empty()) break;

    switch (current_section) {
      case 0: inputs_raw.push_back(path); break;
      case 1: imp_inputs_raw.push_back(path); break;
      case 2: order_only_raw.push_back(path); break;
      case 3: validations_raw.push_back(path); break;
    }
  }

  if (!ExpectToken(Lexer::NEWLINE, err)) {
    // Try EOF
    Lexer::Token t = lexer_.ReadToken();
    if (t == Lexer::TEOF) {
      // OK
    } else {
      return false;
    }
  }

  // Create a binding environment for build-level variables
  BindingEnv* edge_env = new BindingEnv(env_);

  // Read indented bindings
  for (;;) {
    Lexer::Token token = lexer_.ReadToken();
    if (token == Lexer::NEWLINE) continue;
    if (token != Lexer::INDENT) {
      lexer_.p_ = lexer_.last_token_;
      break;
    }

    std::string key;
    if (!lexer_.ReadIdent(&key)) {
      return lexer_.Error("expected binding key", err);
    }

    if (!ExpectToken(Lexer::EQUALS, err)) return false;

    EvalString value;
    if (!lexer_.ReadVarValue(&value, err)) return false;

    Lexer::Token nl = lexer_.ReadToken();
    if (nl != Lexer::NEWLINE && nl != Lexer::TEOF) {
      return lexer_.Error("expected newline after binding", err);
    }

    std::string evaluated = EvalStringEvaluate(value, edge_env);
    edge_env->AddBinding(key, evaluated);
  }

  // Now evaluate all paths and create the edge
  // Evaluate outputs
  auto EvalPaths = [&](const std::vector<EvalString>& raws, std::string* err) 
      -> std::vector<std::string> {
    std::vector<std::string> result;
    for (const auto& raw : raws) {
      std::string path = EvalStringEvaluate(raw, edge_env);
      if (path.empty()) {
        *err = "empty path";
        return {};
      }
      uint64_t slash_bits = 0;
      CanonicalizePath(&path, &slash_bits, err);
      result.push_back(path);
    }
    return result;
  };

  std::string path_err;
  std::vector<std::string> outputs = EvalPaths(outputs_raw, &path_err);
  if (!path_err.empty()) return lexer_.Error(path_err, err);

  std::vector<std::string> imp_outputs = EvalPaths(imp_outputs_raw, &path_err);
  if (!path_err.empty()) return lexer_.Error(path_err, err);

  std::vector<std::string> inputs = EvalPaths(inputs_raw, &path_err);
  if (!path_err.empty()) return lexer_.Error(path_err, err);

  std::vector<std::string> imp_inputs = EvalPaths(imp_inputs_raw, &path_err);
  if (!path_err.empty()) return lexer_.Error(path_err, err);

  std::vector<std::string> order_only = EvalPaths(order_only_raw, &path_err);
  if (!path_err.empty()) return lexer_.Error(path_err, err);

  std::vector<std::string> validations = EvalPaths(validations_raw, &path_err);
  if (!path_err.empty()) return lexer_.Error(path_err, err);

  if (outputs.empty() && imp_outputs.empty()) {
    return lexer_.Error("expected output file", err);
  }

  // Create the edge
  Edge* edge = state_->AddEdge(rule);
  edge->env_ = edge_env;
  edge->edge_env_ = edge_env;

  // Set pool
  std::string pool_name = edge_env->bindings_.count("pool") 
      ? edge_env->bindings_["pool"] 
      : (rule->GetBinding("pool") ? EvalStringEvaluate(*rule->GetBinding("pool"), edge_env) : "");

  if (!pool_name.empty()) {
    Pool* pool = state_->LookupPool(pool_name);
    if (!pool) {
      return lexer_.Error("unknown pool name '" + pool_name + "'", err);
    }
    edge->pool_ = pool;
  }

  // Build up $in, $out, $in_newline
  std::string in_str, out_str, in_newline_str;
  for (const auto& s : inputs) {
    if (!in_str.empty()) in_str += ' ';
    if (!in_newline_str.empty()) in_newline_str += '\n';
    in_str += s;
    in_newline_str += s;
  }
  for (const auto& s : imp_inputs) {
    if (!in_str.empty()) in_str += ' ';
    if (!in_newline_str.empty()) in_newline_str += '\n';
    in_str += s;
    in_newline_str += s;
  }

  for (const auto& s : outputs) {
    if (!out_str.empty()) out_str += ' ';
    out_str += s;
  }

  edge_env->AddBinding("in", in_str);
  edge_env->AddBinding("in_newline", in_newline_str);
  edge_env->AddBinding("out", out_str);

  // Assign outputs
  int num_outputs = (int)(outputs.size() + imp_outputs.size());
  edge->implicit_outs_ = (int)imp_outputs.size();

  for (const auto& out : outputs) {
    Node* node = state_->GetNode(out);
    if (node->in_edge() != nullptr) {
      Edge* old = node->in_edge();
      if (old->IsPhony()) {
        // ignore
      } else {
        // Duplicate edge
        if (options_.dupe_edge_action_ == kDupeEdgeActionError) {
          return lexer_.Error("multiple rules generate '" + out + "'", err);
        } else {
          Warning("multiple rules generate %s; builds involving this target will not be correct; "
                  "continuing anyway", out.c_str());
        }
      }
    }
    node->set_in_edge(edge);
    edge->outputs_.push_back(node);
  }
  for (const auto& out : imp_outputs) {
    Node* node = state_->GetNode(out);
    if (node->in_edge() != nullptr) {
      if (options_.dupe_edge_action_ == kDupeEdgeActionError) {
        return lexer_.Error("multiple rules generate '" + out + "'", err);
      }
    }
    node->set_in_edge(edge);
    edge->outputs_.push_back(node);
  }

  // Assign inputs
  edge->implicit_deps_ = (int)(imp_inputs.size());
  edge->order_only_deps_ = (int)(order_only.size());

  for (const auto& in : inputs) {
    Node* node = state_->GetNode(in);
    node->out_edges_.push_back(edge);
    edge->inputs_.push_back(node);
  }
  for (const auto& in : imp_inputs) {
    Node* node = state_->GetNode(in);
    node->out_edges_.push_back(edge);
    edge->inputs_.push_back(node);
  }
  for (const auto& in : order_only) {
    Node* node = state_->GetNode(in);
    node->out_edges_.push_back(edge);
    edge->inputs_.push_back(node);
  }

  // Validations
  for (const auto& val : validations) {
    Node* node = state_->GetNode(val);
    node->validation_out_edges_.push_back(edge);
    edge->validations_.push_back(node);
  }

  // Handle phony cycle
  if (rule == &State::kPhonyRule) {
    for (auto* out_node : edge->outputs_) {
      for (auto* in_node : edge->inputs_) {
        if (out_node == in_node) {
          // Phony cycle
          if (options_.phony_cycle_action_ == kPhonyCycleActionError) {
            return lexer_.Error("phony target '" + out_node->path() + 
                               "' names itself as an input", err);
          } else {
            Warning("phony target '%s' names itself as an input; ignoring [-w phonycycle=warn]",
                    out_node->path().c_str());
            // Remove from inputs
            edge->inputs_.erase(
                std::remove(edge->inputs_.begin(), edge->inputs_.end(), in_node),
                edge->inputs_.end());
            break;
          }
        }
      }
    }
  }

  return true;
}

bool ManifestParser::ParsePool(std::string* err) {
  std::string name;
  if (!lexer_.ReadIdent(&name)) {
    return lexer_.Error("expected pool name", err);
  }

  if (!ExpectToken(Lexer::NEWLINE, err)) return false;

  if (state_->LookupPool(name)) {
    return lexer_.Error("duplicate pool '" + name + "'", err);
  }

  int depth = 0;

  // Read indented bindings
  for (;;) {
    Lexer::Token token = lexer_.ReadToken();
    if (token == Lexer::NEWLINE) continue;
    if (token != Lexer::INDENT) {
      lexer_.p_ = lexer_.last_token_;
      break;
    }

    std::string key;
    if (!lexer_.ReadIdent(&key)) {
      return lexer_.Error("expected variable", err);
    }

    if (!ExpectToken(Lexer::EQUALS, err)) return false;

    EvalString value;
    if (!lexer_.ReadVarValue(&value, err)) return false;

    lexer_.ReadToken();  // newline

    if (key == "depth") {
      std::string val_str = EvalStringEvaluate(value, env_);
      depth = atoi(val_str.c_str());
      if (depth < 0) {
        return lexer_.Error("invalid pool depth", err);
      }
    }
  }

  Pool* pool = new Pool(name, depth);
  state_->AddPool(pool);
  return true;
}

bool ManifestParser::ParseDefault(std::string* err) {
  bool has_defaults = false;

  for (;;) {
    EvalString path;
    if (!lexer_.ReadPath(&path, err)) return false;
    if (path.empty()) break;

    std::string p = EvalStringEvaluate(path, env_);
    uint64_t slash_bits = 0;
    CanonicalizePath(&p, &slash_bits, err);

    Node* node = state_->LookupNode(p);
    if (!node) {
      return lexer_.Error("unknown target '" + p + "'", err);
    }

    state_->AddDefault(node);
    has_defaults = true;
  }

  if (!has_defaults) {
    return lexer_.Error("expected target name", err);
  }

  Lexer::Token token = lexer_.ReadToken();
  if (token != Lexer::NEWLINE && token != Lexer::TEOF) {
    return lexer_.Error("expected newline, got " + std::string(TokenName(token)), err);
  }

  return true;
}

bool ManifestParser::ParseFileInclude(bool new_scope, std::string* err) {
  EvalString path;
  if (!lexer_.ReadPath(&path, err)) return false;

  std::string p = EvalStringEvaluate(path, env_);

  Lexer::Token token = lexer_.ReadToken();
  if (token != Lexer::NEWLINE && token != Lexer::TEOF) {
    return lexer_.Error("expected newline after include/subninja path", err);
  }

  BindingEnv* parent_env = env_;
  if (new_scope) {
    env_ = new BindingEnv(parent_env);
  }

  // Save current lexer state
  Lexer saved_lexer = lexer_;
  std::string saved_input = input_storage_;

  std::string sub_err;
  bool ok = Load(p, &sub_err);
  if (!ok) {
    *err = sub_err;
    // Restore
    lexer_ = saved_lexer;
    input_storage_ = saved_input;
    if (new_scope) {
      delete env_;
      env_ = parent_env;
    }
    return false;
  }

  // Restore
  lexer_ = saved_lexer;
  input_storage_ = saved_input;

  if (new_scope) {
    delete env_;
    env_ = parent_env;
  }

  return true;
}
