bool ManifestParser::Load(const std::string& filename, std::string* err, const Lexer* parent) {
  std::string contents;
  std::string read_err;
  if (!ReadFile(filename, &contents, &read_err)) {
    *err = "loading '" + filename + "': " + read_err;
    return false;
  }
  contents += "\n";  // Make sure file ends with newline
  return Parse(filename, contents, err);
}

bool ManifestParser::ParseTest(const std::string& input, std::string* err) {
  return Parse("input", input + "\n", err);
}

bool ManifestParser::Parse(const std::string& filename, const std::string& input, std::string* err) {
  input_storage_ = input;
  lexer_ = Lexer(filename, input_storage_);

  for (;;) {
    Lexer::Token token = lexer_.ReadToken();

    switch (token) {
      case Lexer::TEOF:
        return true;

      case Lexer::NEWLINE:
        continue;

      case Lexer::RULE:
        if (!ParseRule(err)) return false;
        break;

      case Lexer::BUILD:
        if (!ParseBuild(err)) return false;
        break;

      case Lexer::DEFAULT:
        if (!ParseDefault(err)) return false;
        break;

      case Lexer::POOL:
        if (!ParsePool(err)) return false;
        break;

      case Lexer::INCLUDE:
        if (!ParseFileInclude(false, err)) return false;
        break;

      case Lexer::SUBNINJA:
        if (!ParseFileInclude(true, err)) return false;
        break;

      case Lexer::IDENT: {
        // Variable assignment
        lexer_.p_ -= lexer_.p_ - lexer_.last_token_;  // backup to start of ident
        // Actually, ident was already consumed. Let's get it.
        std::string name(lexer_.last_token_, 
                         lexer_.p_);
        // Try reading = value
        if (!ParseVarDecl(err)) return false;
        break;
      }

      case Lexer::INDENT:
        // Top-level indented lines are errors, but let's be lenient
        // and skip them
        lexer_.AdvanceToNewline();
        break;

      default: {
        // Check if it's an ident we need to handle
        std::string msg = std::string("unexpected ") + TokenName(token);
        return lexer_.Error(msg, err);
      }
    }
  }
}

bool ManifestParser::ParseVarDecl(std::string* err) {
  // We already consumed the identifier token
  // Re-read it from last_token_
  std::string name(lexer_.last_token_, lexer_.p_);
  // Remove trailing whitespace
  while (!name.empty() && (name.back() == ' ' || name.back() == '\t'))
    name.pop_back();

  Lexer::Token token = lexer_.ReadToken();
  if (token != Lexer::EQUALS) {
    return lexer_.Error("expected = sign", err);
  }

  EvalString value;
  if (!lexer_.ReadVarValue(&value, err)) return false;

  // Skip to newline
  token = lexer_.ReadToken();
  if (token != Lexer::NEWLINE && token != Lexer::TEOF) {
    return lexer_.Error("expected newline, got " + std::string(TokenName(token)), err);
  }

  std::string evaluated = EvalStringEvaluate(value, env_);
  env_->AddBinding(name, evaluated);
  return true;
}

bool ManifestParser::ExpectToken(Lexer::Token expected, std::string* err) {
  Lexer::Token token = lexer_.ReadToken();
  if (token != expected) {
    std::string msg = std::string("expected ") + TokenName(expected) + 
                      ", got " + TokenName(token);
    return lexer_.Error(msg, err);
  }
  return true;
}

bool ManifestParser::ParseRule(std::string* err) {
  std::string name;
  if (!lexer_.ReadIdent(&name)) {
    return lexer_.Error("expected rule name", err);
  }

  if (!ExpectToken(Lexer::NEWLINE, err)) return false;

  if (state_->rules_.count(name)) {
    // Duplicate rule - it's allowed, later one wins (silently)
  }

  Rule* rule = new Rule(name);

  // Read indented bindings
  for (;;) {
    Lexer::Token token = lexer_.ReadToken();
    if (token == Lexer::NEWLINE) {
      continue;
    }
    if (token != Lexer::INDENT) {
      // Put back
      lexer_.p_ = lexer_.last_token_;
      break;
    }

    // Read key = value
    std::string key;
    if (!lexer_.ReadIdent(&key)) {
      return lexer_.Error("expected binding key", err);
    }

    if (!ExpectToken(Lexer::EQUALS, err)) return false;

    EvalString value;
    if (!lexer_.ReadVarValue(&value, err)) return false;

    if (!ExpectToken(Lexer::NEWLINE, err)) {
      // Try EOF
      if (lexer_.ReadToken() != Lexer::TEOF)
        return false;
    }

    rule->AddBinding(key, value);
  }

  if (!rule->GetBinding("command")) {
    delete rule;
    return lexer_.Error("expected 'command =' line", err);
  }

  state_->AddRule(rule);
  return true;
}

