    if (!lexer_.ReadVarValue(&value, err)) return false;

    Lexer::Token nl = lexer_.ReadToken();
    if (nl != Lexer::NEWLINE && nl != Lexer::TEOF) {
      return lexer_.Error("expected newline after binding", err);
    }

    std::string evaluated = EvalStringEvaluate(value, edge_env);
    edge_env->AddBinding(key, evaluated);
  }

  // Now evaluate all paths and create the edge
  // Evaluate outputs
  auto EvalPaths = [&](const std::vector<EvalString>& raws, std::string* err) 
      -> std::vector<std::string> {
    std::vector<std::string> result;
    for (const auto& raw : raws) {
      std::string path = EvalStringEvaluate(raw, edge_env);
      if (path.empty()) {
        *err = "empty path";
        return {};
      }
      uint64_t slash_bits = 0;
      CanonicalizePath(&path, &slash_bits, err);
      result.push_back(path);
    }
    return result;
  };

  std::string path_err;
  std::vector<std::string> outputs = EvalPaths(outputs_raw, &path_err);
  if (!path_err.empty()) return lexer_.Error(path_err, err);

  std::vector<std::string> imp_outputs = EvalPaths(imp_outputs_raw, &path_err);
  if (!path_err.empty()) return lexer_.Error(path_err, err);

  std::vector<std::string> inputs = EvalPaths(inputs_raw, &path_err);
  if (!path_err.empty()) return lexer_.Error(path_err, err);

  std::vector<std::string> imp_inputs = EvalPaths(imp_inputs_raw, &path_err);
  if (!path_err.empty()) return lexer_.Error(path_err, err);

  std::vector<std::string> order_only = EvalPaths(order_only_raw, &path_err);
  if (!path_err.empty()) return lexer_.Error(path_err, err);

  std::vector<std::string> validations = EvalPaths(validations_raw, &path_err);
  if (!path_err.empty()) return lexer_.Error(path_err, err);

  if (outputs.empty() && imp_outputs.empty()) {
    return lexer_.Error("expected output file", err);
  }

  // Create the edge
  Edge* edge = state_->AddEdge(rule);
  edge->env_ = edge_env;
  edge->edge_env_ = edge_env;

  // Set pool
  std::string pool_name = edge_env->bindings_.count("pool") 
      ? edge_env->bindings_["pool"] 
      : (rule->GetBinding("pool") ? EvalStringEvaluate(*rule->GetBinding("pool"), edge_env) : "");

  if (!pool_name.empty()) {
    Pool* pool = state_->LookupPool(pool_name);
    if (!pool) {
      return lexer_.Error("unknown pool name '" + pool_name + "'", err);
    }
    edge->pool_ = pool;
  }

  // Build up $in, $out, $in_newline
  std::string in_str, out_str, in_newline_str;
  for (const auto& s : inputs) {
    if (!in_str.empty()) in_str += ' ';
    if (!in_newline_str.empty()) in_newline_str += '\n';
    in_str += s;
    in_newline_str += s;
  }
  for (const auto& s : imp_inputs) {
    if (!in_str.empty()) in_str += ' ';
    if (!in_newline_str.empty()) in_newline_str += '\n';
    in_str += s;
    in_newline_str += s;
  }

  for (const auto& s : outputs) {
    if (!out_str.empty()) out_str += ' ';
    out_str += s;
  }

  edge_env->AddBinding("in", in_str);
  edge_env->AddBinding("in_newline", in_newline_str);
  edge_env->AddBinding("out", out_str);

  // Assign outputs
  int num_outputs = (int)(outputs.size() + imp_outputs.size());
  edge->implicit_outs_ = (int)imp_outputs.size();

  for (const auto& out : outputs) {
    Node* node = state_->GetNode(out);
    if (node->in_edge() != nullptr) {
      Edge* old = node->in_edge();
      if (old->IsPhony()) {
        // ignore
      } else {
        // Duplicate edge
        if (options_.dupe_edge_action_ == kDupeEdgeActionError) {
          return lexer_.Error("multiple rules generate '" + out + "'", err);
        } else {
          Warning("multiple rules generate %s; builds involving this target will not be correct; "
                  "continuing anyway", out.c_str());
        }
      }
    }
    node->set_in_edge(edge);
    edge->outputs_.push_back(node);
  }
  for (const auto& out : imp_outputs) {
    Node* node = state_->GetNode(out);
    if (node->in_edge() != nullptr) {
      if (options_.dupe_edge_action_ == kDupeEdgeActionError) {
        return lexer_.Error("multiple rules generate '" + out + "'", err);
      }
    }
    node->set_in_edge(edge);
    edge->outputs_.push_back(node);
  }

  // Assign inputs
  edge->implicit_deps_ = (int)(imp_inputs.size());
  edge->order_only_deps_ = (int)(order_only.size());

  for (const auto& in : inputs) {
    Node* node = state_->GetNode(in);
    node->out_edges_.push_back(edge);
    edge->inputs_.push_back(node);
  }
  for (const auto& in : imp_inputs) {
    Node* node = state_->GetNode(in);
    node->out_edges_.push_back(edge);
    edge->inputs_.push_back(node);
  }
  for (const auto& in : order_only) {
    Node* node = state_->GetNode(in);
    node->out_edges_.push_back(edge);
    edge->inputs_.push_back(node);
  }

  // Validations
  for (const auto& val : validations) {
    Node* node = state_->GetNode(val);
    node->validation_out_edges_.push_back(edge);
    edge->validations_.push_back(node);
  }

  // Handle phony cycle
  if (rule == &State::kPhonyRule) {
    for (auto* out_node : edge->outputs_) {
      for (auto* in_node : edge->inputs_) {
        if (out_node == in_node) {
          // Phony cycle
          if (options_.phony_cycle_action_ == kPhonyCycleActionError) {
            return lexer_.Error("phony target '" + out_node->path() + 
                               "' names itself as an input", err);
          } else {
            Warning("phony target '%s' names itself as an input; ignoring [-w phonycycle=warn]",
                    out_node->path().c_str());
            // Remove from inputs
            edge->inputs_.erase(
                std::remove(edge->inputs_.begin(), edge->inputs_.end(), in_node),
                edge->inputs_.end());
            break;
          }
        }
      }
    }
  }

  return true;
}

bool ManifestParser::ParsePool(std::string* err) {
  std::string name;
  if (!lexer_.ReadIdent(&name)) {
    return lexer_.Error("expected pool name", err);
  }

  if (!ExpectToken(Lexer::NEWLINE, err)) return false;

  if (state_->LookupPool(name)) {
    return lexer_.Error("duplicate pool '" + name + "'", err);
  }

  int depth = 0;

  // Read indented bindings
  for (;;) {
    Lexer::Token token = lexer_.ReadToken();
    if (token == Lexer::NEWLINE) continue;
    if (token != Lexer::INDENT) {
      lexer_.p_ = lexer_.last_token_;
      break;
    }

    std::string key;
    if (!lexer_.ReadIdent(&key)) {
      return lexer_.Error("expected variable", err);
    }

    if (!ExpectToken(Lexer::EQUALS, err)) return false;

    EvalString value;
    if (!lexer_.ReadVarValue(&value, err)) return false;

    lexer_.ReadToken();  // newline

    if (key == "depth") {
      std::string val_str = EvalStringEvaluate(value, env_);
      depth = atoi(val_str.c_str());
      if (depth < 0) {
        return lexer_.Error("invalid pool depth", err);
      }
    }
  }

  Pool* pool = new Pool(name, depth);
  state_->AddPool(pool);
  return true;
}

bool ManifestParser::ParseDefault(std::string* err) {
  bool has_defaults = false;

  for (;;) {
    EvalString path;
    if (!lexer_.ReadPath(&path, err)) return false;
    if (path.empty()) break;

    std::string p = EvalStringEvaluate(path, env_);
    uint64_t slash_bits = 0;
    CanonicalizePath(&p, &slash_bits, err);

    Node* node = state_->LookupNode(p);
    if (!node) {
      return lexer_.Error("unknown target '" + p + "'", err);
    }

    state_->AddDefault(node);
    has_defaults = true;
  }

  if (!has_defaults) {
    return lexer_.Error("expected target name", err);
  }

  Lexer::Token token = lexer_.ReadToken();
  if (token != Lexer::NEWLINE && token != Lexer::TEOF) {
    return lexer_.Error("expected newline, got " + std::string(TokenName(token)), err);
  }

  return true;
}

bool ManifestParser::ParseFileInclude(bool new_scope, std::string* err) {
  EvalString path;
  if (!lexer_.ReadPath(&path, err)) return false;

  std::string p = EvalStringEvaluate(path, env_);

  Lexer::Token token = lexer_.ReadToken();
  if (token != Lexer::NEWLINE && token != Lexer::TEOF) {
    return lexer_.Error("expected newline after include/subninja path", err);
  }

  BindingEnv* parent_env = env_;
  if (new_scope) {
    env_ = new BindingEnv(parent_env);
  }

  // Save current lexer state
  Lexer saved_lexer = lexer_;
  std::string saved_input = input_storage_;

  std::string sub_err;
  bool ok = Load(p, &sub_err);
  if (!ok) {
    *err = sub_err;
    // Restore
    lexer_ = saved_lexer;
    input_storage_ = saved_input;
    if (new_scope) {
      delete env_;
      env_ = parent_env;
    }
    return false;
  }

  // Restore
  lexer_ = saved_lexer;
  input_storage_ = saved_input;

  if (new_scope) {
    delete env_;
    env_ = parent_env;
  }

  return true;
}
