  FILE* f = fopen(path.c_str(), "r");
  if (!f) {
    if (errno == ENOENT) return true;
    *err = strerror(errno);
    return false;
  }

  char buf[65536];
  int version = 0;

  // Read header
  if (!fgets(buf, sizeof(buf), f)) {
    fclose(f);
    return true;  // Empty file is OK
  }

  if (sscanf(buf, kFileSignature, &version) != 1) {
    // Not a valid log file - ignore
    fclose(f);
    return true;
  }

  if (version < 7) {
    // Old version - treat as empty
    fclose(f);
    return true;
  }

  while (fgets(buf, sizeof(buf), f)) {
    // Format: start_time\tend_time\tmtime\toutput\tcommand_hash
    int64_t start, end, mtime;
    char output[4096];
    uint64_t hash;

    // Parse line
    char* p = buf;
    char* tab;

    // start_time
    tab = strchr(p, '\t');
    if (!tab) continue;
    *tab = '\0';
    start = atoll(p);
    p = tab + 1;

    // end_time
    tab = strchr(p, '\t');
    if (!tab) continue;
    *tab = '\0';
    end = atoll(p);
    p = tab + 1;

    // mtime
    tab = strchr(p, '\t');
    if (!tab) continue;
    *tab = '\0';
    mtime = (int64_t)strtoull(p, nullptr, 10);
    p = tab + 1;

    // output
    tab = strchr(p, '\t');
    if (!tab) continue;
    *tab = '\0';
    strncpy(output, p, sizeof(output) - 1);
    p = tab + 1;

    // hash (may have newline at end)
    size_t len = strlen(p);
    while (len > 0 && (p[len-1] == '\n' || p[len-1] == '\r')) len--;
    p[len] = '\0';
    hash = (uint64_t)strtoull(p, nullptr, 16);

    LogEntry* entry = new LogEntry();
    entry->output = output;
    entry->start_time = start;
    entry->end_time = end;
    entry->mtime = mtime;
    entry->command_hash = hash;

    auto it = entries_.find(output);
    if (it != entries_.end()) {
      delete it->second;
      it->second = entry;
    } else {
      entries_[output] = entry;
    }
    total_entries_++;
  }

  fclose(f);

  // Check if we should recompact
  if (total_entries_ > (int)entries_.size() * (1 + kMaxDeadRatio)) {
    needs_recompact_ = true;
  }

  return true;
}

bool BuildLog::OpenForWrite(const std::string& path, std::string* err) {
  log_path_ = path;

  if (needs_recompact_) {
    if (!Recompact(path, err)) return false;
  }

  log_file_ = fopen(path.c_str(), "ab");
  if (!log_file_) {
    *err = "opening build log '" + path + "': " + strerror(errno);
    return false;
  }

  // If file is empty, write header
  fseek(log_file_, 0, SEEK_END);
  if (ftell(log_file_) == 0) {
    fprintf(log_file_, kFileSignature, kCurrentVersion);
  }

  return true;
}

bool BuildLog::WriteEntry(const Edge* edge, int64_t start_time, int64_t end_time,
                          int64_t restat_mtime) {
  if (!log_file_) return true;

  for (auto* output : edge->outputs_) {
    std::string cmd = edge->EvaluateCommand(false);
    uint64_t hash = HashCommand(cmd);

    int64_t mtime = restat_mtime > 0 ? restat_mtime : end_time;

    // Update in-memory entry
    LogEntry* entry = LookupByOutput(output->path());
    if (!entry) {
      entry = new LogEntry();
      entry->output = output->path();
      entries_[output->path()] = entry;
    }
    entry->command_hash = hash;
    entry->start_time = start_time;
    entry->end_time = end_time;
    entry->mtime = output->mtime();

    fprintf(log_file_, "%" PRId64 "\t%" PRId64 "\t%" PRId64 "\t%s\t%016" PRIx64 "\n",
            start_time, end_time, output->mtime(), output->path().c_str(), hash);
  }

  fflush(log_file_);
  return true;
}

BuildLog::LogEntry* BuildLog::LookupByOutput(const std::string& path) {
  auto it = entries_.find(path);
  if (it == entries_.end()) return nullptr;
  return it->second;
}

bool BuildLog::Recompact(const std::string& path, std::string* err) {
  std::string tmp_path = path + ".tmp";
  FILE* f = fopen(tmp_path.c_str(), "w");
  if (!f) {
    *err = "opening " + tmp_path + ": " + strerror(errno);
    return false;
  }

  fprintf(f, kFileSignature, kCurrentVersion);

  for (auto& kv : entries_) {
    LogEntry* e = kv.second;
    fprintf(f, "%" PRId64 "\t%" PRId64 "\t%" PRId64 "\t%s\t%016" PRIx64 "\n",
            e->start_time, e->end_time, e->mtime, e->output.c_str(), e->command_hash);
  }

  fclose(f);

  if (rename(tmp_path.c_str(), path.c_str()) < 0) {
    *err = "renaming " + tmp_path + " to " + path + ": " + strerror(errno);
    return false;
  }

  total_entries_ = (int)entries_.size();
  needs_recompact_ = false;
  return true;
}

bool BuildLog::Restat(const std::string& path, const State& state, std::string* err) {
  for (auto& kv : entries_) {
    Node* node = state.LookupNode(kv.first);
    if (node) {
      std::string stat_err;
      if (!node->Stat(&stat_err)) {
        *err = stat_err;
        return false;
      }
      kv.second->mtime = node->mtime();
    }
  }

  if (log_file_) fclose(log_file_);
  log_file_ = nullptr;

  return Recompact(path, err);
}
