    if (size > 0 && fread(buf.data(), 1, size, f) != size) {
      *err = "unexpected EOF in deps log";
      break;
    }

    total_records++;

    if (!is_deps) {
      // Path record
      // The path is the buffer without the last 4 bytes (checksum)
      if (size < 4) {
        *err = "invalid path record size";
        break;
      }

      uint32_t check;
      memcpy(&check, buf.data() + size - 4, 4);

      // Path string (may not be null-terminated)
      int path_len = (int)size - 4;
      // Remove trailing null bytes
      while (path_len > 0 && buf[path_len - 1] == '\0') path_len--;

      std::string path_str((char*)buf.data(), path_len);

      // Verify check: should be ~node_id
      int node_id = (int)nodes_.size();
      uint32_t expected_check = ~(uint32_t)node_id;
      if (check != expected_check) {
        // Corrupted record, skip
        nodes_.push_back(nullptr);
        deps_.push_back(nullptr);
        continue;
      }

      Node* node = state->GetNode(path_str);
      node->set_id(node_id);
      nodes_.push_back(node);
      deps_.push_back(nullptr);
      valid_records++;
    } else {
      // Deps record
      if (size < 12) {
        *err = "invalid deps record size";
        break;
      }

      int32_t path_id;
      memcpy(&path_id, buf.data(), 4);

      int64_t mtime;
      memcpy(&mtime, buf.data() + 4, 8);

      int num_deps = (size - 12) / 4;

      if (path_id < 0 || path_id >= (int)nodes_.size() || !nodes_[path_id]) {
        // Invalid path_id
        continue;
      }

      Deps* deps = new Deps(mtime, num_deps);
      for (int i = 0; i < num_deps; i++) {
        int32_t dep_id;
        memcpy(&dep_id, buf.data() + 12 + i * 4, 4);
        if (dep_id < 0 || dep_id >= (int)nodes_.size()) {
          deps->nodes[i] = nullptr;
        } else {
          deps->nodes[i] = nodes_[dep_id];
        }
      }

      delete deps_[path_id];
      deps_[path_id] = deps;
      valid_records++;
    }
  }

  fclose(f);

  // Check if we need to recompact (too many dead records)
  if (total_records > valid_records * 2) {
    needs_recompact_ = true;
  }

  return true;
}

bool DepsLog::OpenForWrite(const std::string& path, std::string* err) {
  if (needs_recompact_) {
    // Can't recompact here without state
    // Just truncate and rewrite
  }

  file_ = fopen(path.c_str(), "ab");
  if (!file_) {
    *err = "opening deps log '" + path + "': " + strerror(errno);
    return false;
  }

  // If file is empty, write header
  fseek(file_, 0, SEEK_END);
  if (ftell(file_) == 0) {
    if (!WriteHeader()) {
      *err = "writing deps header: " + std::string(strerror(errno));
      return false;
    }
  }

  // Assign IDs to known nodes
  for (size_t i = 0; i < nodes_.size(); i++) {
    if (nodes_[i]) nodes_[i]->set_id((int)i);
  }

  return true;
}

bool DepsLog::WriteHeader() {
  if (fwrite(kFileSignature, 1, 12, file_) != 12) return false;
  uint32_t version = kCurrentVersion;
  if (fwrite(&version, 4, 1, file_) != 1) return false;
  fflush(file_);
  return true;
}

static uint32_t AlignTo4(uint32_t n) {
  return (n + 3) & ~3;
}

bool DepsLog::WriteNode(Node* node, int path_id) {
  const std::string& path = node->path();
  uint32_t path_len = (uint32_t)path.size();
  uint32_t padded_size = AlignTo4(path_len);
  uint32_t total_size = padded_size + 4;  // path + checksum

  if (fwrite(&total_size, 4, 1, file_) != 1) return false;

  if (fwrite(path.c_str(), 1, path_len, file_) != path_len) return false;

  // Write padding zeros
  if (padded_size > path_len) {
    uint32_t padding = 0;
    if (fwrite(&padding, 1, padded_size - path_len, file_) != padded_size - path_len) return false;
  }

  // Write checksum = ~path_id
  uint32_t check = ~(uint32_t)path_id;
  if (fwrite(&check, 4, 1, file_) != 1) return false;

  return true;
}

bool DepsLog::RecordDeps(Node* node, int64_t mtime, const std::vector<Node*>& nodes) {
  if (!file_) return true;

  // Make sure all nodes have IDs
  auto EnsureId = [this](Node* n) {
    if (n->id() < 0) {
      int id = (int)nodes_.size();
      n->set_id(id);
      nodes_.push_back(n);
      deps_.push_back(nullptr);
      if (!WriteNode(n, id)) return false;
    }
    return true;
  };

  if (!EnsureId(node)) return false;
  for (auto* dep : nodes) {
    if (dep && !EnsureId(dep)) return false;
  }

  // Write deps record
  uint32_t num_deps = (uint32_t)nodes.size();
  uint32_t record_size = 4 + 8 + num_deps * 4;  // node_id + mtime + deps
  uint32_t size_word = record_size | 0x80000000;  // set high bit for deps record

  if (fwrite(&size_word, 4, 1, file_) != 1) return false;

  int32_t node_id = node->id();
  if (fwrite(&node_id, 4, 1, file_) != 1) return false;
  if (fwrite(&mtime, 8, 1, file_) != 1) return false;

  for (auto* dep : nodes) {
    int32_t dep_id = dep ? dep->id() : -1;
    if (fwrite(&dep_id, 4, 1, file_) != 1) return false;
  }

  fflush(file_);

  // Update in-memory
  delete deps_[node->id()];
  Deps* deps = new Deps(mtime, (int)nodes.size());
  for (size_t i = 0; i < nodes.size(); i++) {
    deps->nodes[i] = nodes[i];
  }
  deps_[node->id()] = deps;

  return true;
}

DepsLog::Deps* DepsLog::GetDeps(Node* node) {
  if (node->id() < 0 || node->id() >= (int)deps_.size()) return nullptr;
  return deps_[node->id()];
}

bool DepsLog::Recompact(const std::string& path, const State& state, std::string* err) {
  Close();

  std::string tmp_path = path + ".tmp";
  FILE* f = fopen(tmp_path.c_str(), "wb");
  if (!f) {
    *err = "opening " + tmp_path + ": " + strerror(errno);
    return false;
  }

  // Write header
  if (fwrite(kFileSignature, 1, 12, f) != 12) {
    fclose(f);
    *err = "write error";
    return false;
  }
  uint32_t version = kCurrentVersion;
  if (fwrite(&version, 4, 1, f) != 1) {
    fclose(f);
    *err = "write error";
    return false;
  }

  // Collect nodes with valid deps
  std::map<int, int> old_to_new;
  int new_id = 0;

  for (size_t i = 0; i < nodes_.size(); i++) {
    Node* node = nodes_[i];
    if (!node) continue;
    if (!deps_[i]) {
      // Check if node still exists in state
      if (!state.LookupNode(node->path())) continue;
    }
    old_to_new[i] = new_id++;

    // Write path record
    const std::string& path_str = node->path();
    uint32_t path_len = (uint32_t)path_str.size();
    uint32_t padded_size = ((path_len + 3) / 4) * 4;
    uint32_t total_size = padded_size + 4;

    fwrite(&total_size, 4, 1, f);
    fwrite(path_str.c_str(), 1, path_len, f);
    if (padded_size > path_len) {
      uint32_t pad = 0;
      fwrite(&pad, 1, padded_size - path_len, f);
    }
    int new_node_id = old_to_new[i];
    uint32_t check = ~(uint32_t)new_node_id;
    fwrite(&check, 4, 1, f);
  }

  // Write deps records
  for (size_t i = 0; i < nodes_.size(); i++) {
    if (!nodes_[i] || !deps_[i]) continue;
    auto it = old_to_new.find(i);
    if (it == old_to_new.end()) continue;

    Deps* deps = deps_[i];
    int num_valid_deps = 0;
    for (int j = 0; j < deps->node_count; j++) {
      if (deps->nodes[j] && old_to_new.count(deps->nodes[j]->id()))
        num_valid_deps++;
    }

    uint32_t record_size = 4 + 8 + num_valid_deps * 4;
    uint32_t size_word = record_size | 0x80000000;
    fwrite(&size_word, 4, 1, f);

    int32_t new_node_id = it->second;
    fwrite(&new_node_id, 4, 1, f);
    fwrite(&deps->mtime, 8, 1, f);

    for (int j = 0; j < deps->node_count; j++) {
      if (!deps->nodes[j]) continue;
      int old_id = deps->nodes[j]->id();
      auto dep_it = old_to_new.find(old_id);
      if (dep_it == old_to_new.end()) continue;
      int32_t new_dep_id = dep_it->second;
      fwrite(&new_dep_id, 4, 1, f);
    }
  }

  fclose(f);

  if (rename(tmp_path.c_str(), path.c_str()) < 0) {
    *err = "renaming: " + std::string(strerror(errno));
    return false;
  }

  // Update node IDs
  for (auto& kv : old_to_new) {
    if (nodes_[kv.first]) nodes_[kv.first]->set_id(kv.second);
  }

  needs_recompact_ = false;
  return true;
}
