    // Handle line continuation
    if (*p == '\\') {
      ++p;
      if (p < end && (*p == '\n' || *p == '\r')) {
        if (*p == '\r') ++p;
        if (p < end && *p == '\n') ++p;
        continue;  // Continue to next line
