    if (IsNewline(*p)) {
      // Check if next line is a continuation
      const char* q = p + 1;
      if (*p == '\r' && q < end && *q == '\n') ++q;
      // If the previous character was '\\', it was a continuation
      // already handled above
      break;  // End of deps
    }

    // Read a path
    std::string dep;
    while (p < end && !IsSpace(*p) && !IsNewline(*p)) {
      if (*p == '\\' && p + 1 < end) {
        ++p;
        if (*p == ' ') {
          dep += ' ';
          ++p;
          continue;
        } else if (*p == '\\') {
          dep += '\\';
          ++p;
          continue;
