  DependencyScan(State* state, BuildLog* build_log, DepsLog* deps_log, const NinjaOptions& opts)
      : state_(state), build_log_(build_log), deps_log_(deps_log), opts_(opts) {}

  bool RecomputeOutputDirty(Edge* edge, Node* most_recent_input,
