#include "subprocess.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/wait.h>
#include <sys/select.h>
#include <errno.h>
#include <signal.h>

Subprocess::Subprocess(bool use_console) 
    : fd_(-1), pid_(-1), use_console_(use_console), 
      exit_code_(-1), done_(false), failed_(false) {}

Subprocess::~Subprocess() {
  if (fd_ >= 0) close(fd_);
}

bool Subprocess::Start(const std::string& command) {
  int output_pipe[2];

  if (!use_console_) {
    if (pipe(output_pipe) < 0) return false;
  }

  pid_ = fork();
  if (pid_ < 0) {
    if (!use_console_) {
      close(output_pipe[0]);
      close(output_pipe[1]);
    }
    return false;
  }

  if (pid_ == 0) {
    // Child process
    if (!use_console_) {
      close(output_pipe[0]);
      dup2(output_pipe[1], STDOUT_FILENO);
      dup2(output_pipe[1], STDERR_FILENO);
      close(output_pipe[1]);
    }

    execl("/bin/sh", "/bin/sh", "-c", command.c_str(), nullptr);
    _exit(127);
  }

  // Parent process
  if (!use_console_) {
    close(output_pipe[1]);
    fd_ = output_pipe[0];

    // Make non-blocking
    int flags = fcntl(fd_, F_GETFL, 0);
    fcntl(fd_, F_SETFL, flags | O_NONBLOCK);
  }

  return true;
}

bool Subprocess::Done() const {
  return done_;
}

std::string Subprocess::GetOutput() const {
  return output_;
}

int Subprocess::GetExitCode() const {
  return exit_code_;
}

SubprocessSet::SubprocessSet() {}

SubprocessSet::~SubprocessSet() {
  Clear();
}

Subprocess* SubprocessSet::Add(const std::string& command, bool use_console) {
  Subprocess* subproc = new Subprocess(use_console);
  if (!subproc->Start(command)) {
    delete subproc;
    return nullptr;
  }
  running_.push_back(subproc);
  return subproc;
}

bool SubprocessSet::DoWork() {
  if (running_.empty()) return false;

  // Build fd_set for select
  fd_set read_fds;
  FD_ZERO(&read_fds);
  int max_fd = -1;

  for (auto* sub : running_) {
    if (sub->fd_ >= 0) {
      FD_SET(sub->fd_, &read_fds);
      if (sub->fd_ > max_fd) max_fd = sub->fd_;
    }
  }

  if (max_fd < 0) {
    // All use_console subprocesses - wait for one to finish
    int status;
    pid_t pid = waitpid(-1, &status, 0);
    if (pid > 0) {
      for (auto it = running_.begin(); it != running_.end(); ++it) {
        Subprocess* sub = *it;
        if (sub->pid_ == pid) {
          sub->exit_code_ = WIFEXITED(status) ? WEXITSTATUS(status) : 1;
          sub->done_ = true;
          sub->failed_ = sub->exit_code_ != 0;
          finished_.push_back(sub);
          running_.erase(it);
          return true;
        }
      }
    }
    return false;
  }

  struct timeval tv;
  tv.tv_sec = 0;
  tv.tv_usec = 50000;  // 50ms timeout

  int n = select(max_fd + 1, &read_fds, nullptr, nullptr, &tv);

  if (n < 0) {
    if (errno == EINTR) return false;
    return false;
  }

  // Read from ready fds
  for (auto* sub : running_) {
    if (sub->fd_ >= 0 && FD_ISSET(sub->fd_, &read_fds)) {
      char buf[4096];
      ssize_t n;
      while ((n = read(sub->fd_, buf, sizeof(buf))) > 0) {
        sub->output_.append(buf, n);
      }
      if (n == 0 || (n < 0 && errno != EAGAIN && errno != EWOULDBLOCK)) {
        // EOF or error - subprocess likely finished
      }
    }
  }

  // Check for finished processes (non-blocking)
  bool any_finished = false;
  auto it = running_.begin();
  while (it != running_.end()) {
    Subprocess* sub = *it;
    int status;
    pid_t result = waitpid(sub->pid_, &status, WNOHANG);
    if (result > 0) {
      // Process finished - read any remaining output
      if (sub->fd_ >= 0) {
        char buf[4096];
        ssize_t n;
        // Set to blocking temporarily to drain
        int flags = fcntl(sub->fd_, F_GETFL, 0);
        fcntl(sub->fd_, F_SETFL, flags & ~O_NONBLOCK);
        while ((n = read(sub->fd_, buf, sizeof(buf))) > 0) {
          sub->output_.append(buf, n);
        }
        close(sub->fd_);
        sub->fd_ = -1;
      }
      sub->exit_code_ = WIFEXITED(status) ? WEXITSTATUS(status) : 1;
      sub->done_ = true;
      sub->failed_ = sub->exit_code_ != 0;
      finished_.push_back(sub);
      it = running_.erase(it);
      any_finished = true;
    } else {
      ++it;
    }
  }

  return any_finished || n > 0;
}

Subprocess* SubprocessSet::NextFinished() {
  if (finished_.empty()) return nullptr;
  Subprocess* sub = finished_.front();
  finished_.erase(finished_.begin());
  return sub;
}

void SubprocessSet::Clear() {
  for (auto* sub : running_) {
    kill(sub->pid_, SIGTERM);
    delete sub;
  }
  running_.clear();
  for (auto* sub : finished_) delete sub;
  finished_.clear();
}
