// ===== Builder =====

Builder::Builder(State* state, const NinjaOptions& opts,
                 BuildLog* build_log, DepsLog* deps_log)
    : state_(state), opts_(opts), plan_(&scan_),
      scan_(state, build_log, opts),
      build_log_(build_log), deps_log_(deps_log) {
  scan_.deps_log_ = deps_log;
  status_ = new BuildStatus(opts);
  subprocs_ = new SubprocessSet();
  build_start_time_ = 0;
}

Builder::~Builder() {
  delete status_;
  delete subprocs_;
}

bool Builder::AddTargetName(const std::string& name, std::string* err) {
  Node* node = state_->LookupNode(name);
  if (!node) {
    *err = "unknown target '" + name + "'";
    return false;
  }
  return AddTarget(node, err);
}

bool Builder::AddTarget(Node* node, std::string* err) {
  if (!scan_.RecomputeDirty(node, err)) return false;
  if (node->in_edge() && node->in_edge()->outputs_ready_) {
    return true;  // Nothing to do
  }
  return plan_.AddTarget(node, err);
}

bool Builder::AlreadyUpToDate() const {
  return plan_.wanted_edges() == 0;
}

bool Builder::Build(std::string* err) {
  status_->BuildStarted();
  status_->PlanHasTotalEdges(plan_.command_edges());

  int64_t start_time = GetTimeMillis();
  build_start_time_ = start_time;

  int pending = 0;
  int failures = 0;

  while (plan_.more_to_do() || pending > 0) {
    // Start new jobs up to parallelism limit
    while ((opts_.parallelism == 0 || pending < opts_.parallelism)) {
      // Check load average
      if (opts_.max_load_average > 0) {
        double load = 0;
        FILE* f = fopen("/proc/loadavg", "r");
        if (f) {
          fscanf(f, "%lf", &load);
          fclose(f);
        }
        if (load >= opts_.max_load_average && pending > 0) break;
      }

      Edge* edge = plan_.FindWork();
      if (!edge) break;

      std::string start_err;
      if (!StartEdge(edge, &start_err)) {
        *err = start_err;
        return false;
      }
      pending++;
    }

    if (pending == 0) break;

    // Wait for a job to finish
    bool any_done = false;
    do {
      any_done = subprocs_->DoWork();
    } while (!any_done && !subprocs_->finished_.empty() && subprocs_->running_.empty());

    // Process finished subprocesses
    while (Subprocess* subproc = subprocs_->NextFinished()) {
      Edge* edge = running_[subproc];
      running_.erase(subproc);
      pending--;

      bool success = !subproc->failed_;
      std::string output = subproc->GetOutput();
      int64_t end_time = GetTimeMillis();
      int64_t edge_start = edge->command_start_time_;

      if (!success) {
        failures++;

        // Print failure info
        fprintf(stdout, "FAILED: [code=%d] ", subproc->exit_code_);
        for (auto* out : edge->outputs_) {
          fprintf(stdout, "%s ", out->path().c_str());
        }
        fprintf(stdout, "\n");

        // Print command
        fprintf(stdout, "%s\n", edge->EvaluateCommand().c_str());
        fflush(stdout);
      }

      std::string finish_err;
      if (!FinishEdge(edge, success, &finish_err, output, edge_start, end_time)) {
        if (!err->empty()) {
          *err = finish_err;
          return false;
        }
      }

      delete subproc;

      if (!success) {
        if (opts_.failures_allowed == 0 || failures < opts_.failures_allowed) {
          continue;
        } else {
          // Stop starting new jobs
          break;
        }
      }
    }

    if (failures > 0 && (opts_.failures_allowed == 1 || 
        failures >= opts_.failures_allowed)) {
      // Wait for remaining jobs
      while (pending > 0) {
        bool done = false;
        do {
          done = subprocs_->DoWork();
        } while (!done && subprocs_->running_.size() > 0);

        while (Subprocess* subproc = subprocs_->NextFinished()) {
          Edge* edge = running_[subproc];
          running_.erase(subproc);
          pending--;

          bool success = !subproc->failed_;
          std::string output = subproc->GetOutput();
          int64_t end_time = GetTimeMillis();

          if (!success) {
            failures++;
            fprintf(stdout, "FAILED: [code=%d] ", subproc->exit_code_);
            for (auto* out : edge->outputs_) fprintf(stdout, "%s ", out->path().c_str());
            fprintf(stdout, "\n");
            fprintf(stdout, "%s\n", edge->EvaluateCommand().c_str());
            fflush(stdout);
          }

          std::string finish_err;
          FinishEdge(edge, success, &finish_err, output, edge->command_start_time_, end_time);
          delete subproc;
        }
      }
      break;
    }
  }

  if (failures > 0) {
    if (failures == 1) {
      *err = "subcommand failed.";
    } else {
      *err = "cannot make progress due to previous errors.";
    }
    return false;
  }

  return true;
}

static bool MakeDirs(const std::string& path) {
  // Create parent directories
  std::string dir;
  for (size_t i = 0; i < path.size(); i++) {
    if (path[i] == '/') {
      if (!dir.empty()) {
        struct stat st;
        if (stat(dir.c_str(), &st) < 0) {
          if (errno == ENOENT) {
            if (mkdir(dir.c_str(), 0777) < 0 && errno != EEXIST) return false;
          }
        }
      }
    }
    dir += path[i];
  }
  return true;
}

bool Builder::StartEdge(Edge* edge, std::string* err) {
  if (edge->IsPhony()) {
    // Mark outputs as built
    int64_t now = GetTimeMillis();
    status_->BuildEdgeStarted(edge, now);

    std::string finish_err;
    FinishEdge(edge, true, &finish_err, "", now, now);
    return true;
  }

  int64_t start_time = GetTimeMillis() - build_start_time_;
  edge->command_start_time_ = start_time;

  status_->BuildEdgeStarted(edge, GetTimeMillis());

  if (opts_.dry_run) {
    // Don't actually run
    std::string finish_err;
    FinishEdge(edge, true, &finish_err, "", start_time, start_time);
    return true;
  }

  // Create output directories
  for (auto* output : edge->outputs_) {
    MakeDirs(output->path());
  }

  // Write response file if needed
  std::string rspfile = edge->GetBinding("rspfile");
  std::string rspfile_content = edge->GetBinding("rspfile_content");
  if (!rspfile.empty() && !rspfile_content.empty()) {
    FILE* f = fopen(rspfile.c_str(), "w");
    if (!f) {
      *err = "opening rspfile '" + rspfile + "': " + strerror(errno);
      return false;
    }
    fwrite(rspfile_content.c_str(), 1, rspfile_content.size(), f);
    fclose(f);
  }

  std::string command = edge->EvaluateCommand();
  bool use_console = (edge->pool_ == &State::kConsolePool);

  Subprocess* subproc = subprocs_->Add(command, use_console);
  if (!subproc) {
    *err = "failed to start subprocess";
    return false;
  }

  running_[subproc] = edge;
  return true;
}

