bool DependencyScan::LoadDeps(Edge* edge, std::string* err) {
  if (!deps_log_) return true;

  for (auto* output : edge->outputs_) {
    DepsLog::Deps* deps = deps_log_->GetDeps(output);
    if (!deps) continue;

    // Add deps as implicit inputs
    for (int i = 0; i < deps->node_count; i++) {
      Node* dep_node = deps->nodes[i];
      if (!dep_node) continue;

      // Check if already an input
      bool found = false;
      for (auto* in : edge->inputs_) {
        if (in == dep_node) { found = true; break; }
      }
      if (!found) {
        edge->inputs_.push_back(dep_node);
        dep_node->out_edges_.push_back(edge);
        edge->implicit_deps_++;
      }
    }
  }
  return true;
}

static bool EdgeIsPhony(const Edge* edge) {
  return edge->rule_->name() == "phony";
}

bool DependencyScan::RecomputeOutputDirty(Edge* edge, Node* most_recent_input,
                                           std::string* err) {
  bool generator = edge->GetBindingBool("generator");
  bool restat = edge->GetBindingBool("restat");

  for (auto* output : edge->outputs_) {
    std::string stat_err;
    if (!output->Stat(&stat_err)) {
      *err = stat_err;
      return false;
    }

    if (!output->exists()) {
      if (opts_.debug_explain)
        fprintf(stderr, "ninja explain: output %s doesn't exist\n", 
                output->path().c_str());
      output->set_dirty(true);
      edge->outputs_ready_ = false;
      continue;
    }

    // Check if command changed
    if (!generator && build_log_) {
      BuildLog::LogEntry* entry = build_log_->LookupByOutput(output->path());
      if (entry) {
        std::string cmd = edge->EvaluateCommand();
        uint64_t hash = HashCommand(cmd);
        if (hash != entry->command_hash) {
          if (opts_.debug_explain)
            fprintf(stderr, "ninja explain: command line changed for %s\n",
                    output->path().c_str());
          output->set_dirty(true);
          edge->outputs_ready_ = false;
          continue;
        }
      }
    }

    // Check timestamps
    if (most_recent_input && output->mtime() < most_recent_input->mtime()) {
      if (opts_.debug_explain)
        fprintf(stderr, "ninja explain: output %s older than most recent input %s "
                "(%" PRId64 " vs %" PRId64 ")\n",
                output->path().c_str(), most_recent_input->path().c_str(),
                output->mtime(), most_recent_input->mtime());
      output->set_dirty(true);
      edge->outputs_ready_ = false;
    }
  }
  return true;
}

bool DependencyScan::RecomputeDirty(Node* node, std::string* err) {
  std::vector<Node*> nodes = {node};
  return RecomputeDirty(&nodes, err);
}

bool DependencyScan::RecomputeDirty(std::vector<Node*>* nodes, std::string* err) {
  // We use iterative traversal with DFS
  struct Frame {
    Node* node;
    Edge* edge;
    int input_idx;
  };

  std::vector<Frame> stack;
  std::set<Edge*> visited_edges;

  for (auto* start : *nodes) {
    if (!start->in_edge()) {
      // Source file
      std::string stat_err;
      if (!start->Stat(&stat_err)) {
        *err = stat_err;
        return false;
      }
      continue;
    }
    stack.push_back({start, nullptr, -1});
  }

  // Process stack
  std::set<Node*> in_stack;
  std::vector<Node*> work_stack;

  // Use recursive DFS with cycle detection
  std::function<bool(Node*)> Visit = [&](Node* node) -> bool {
    if (in_stack.count(node)) return true;  // cycle
    if (!node->stat_unchecked() && !node->dirty()) return true;  // already processed

    Edge* edge = node->in_edge();
    if (!edge) {
      std::string stat_err;
      if (!node->Stat(&stat_err)) {
        *err = stat_err;
        return false;
      }
      return true;
    }

    if (edge->mark_ == Edge::VISIT_DONE) return true;
    if (edge->mark_ == Edge::VISIT_IN_STACK) return true;  // cycle

    edge->mark_ = Edge::VISIT_IN_STACK;
    in_stack.insert(node);

    // Load deps from deps log
    if (!LoadDeps(edge, err)) return false;

    // Visit all inputs
    Node* most_recent_input = nullptr;
    bool input_ready = true;
    bool deps_missing = false;

    for (auto* input : edge->inputs_) {
      if (!Visit(input)) return false;

      std::string stat_err;
      if (!input->StatIfPossible(&stat_err)) {
        *err = stat_err;
        return false;
      }

      if (input->dirty()) {
        if (edge->mark_ != Edge::VISIT_DONE)
          edge->outputs_ready_ = false;
      }

      if (input->mtime() > 0 && (!most_recent_input || 
          input->mtime() > most_recent_input->mtime())) {
        most_recent_input = input;
      }
    }

    // Check if outputs need rebuilding
    if (!EdgeIsPhony(edge)) {
      if (!RecomputeOutputDirty(edge, most_recent_input, err)) return false;
    } else {
      // Phony: dirty if any input is dirty
      bool any_input_dirty = false;
      for (auto* input : edge->inputs_) {
        if (input->dirty()) { any_input_dirty = true; break; }
      }
      if (!any_input_dirty) {
        // Phony is dirty if any output doesn't exist (with no deps)
        if (edge->inputs_.empty()) {
          for (auto* output : edge->outputs_) {
            std::string stat_err;
            if (!output->Stat(&stat_err)) {
              *err = stat_err;
              return false;
            }
            if (!output->exists()) {
              output->set_dirty(true);
            }
          }
        } else {
          // Phony with inputs: dirty if any input is dirty
          // Already handled above
        }
      } else {
        for (auto* output : edge->outputs_) {
          output->set_dirty(true);
        }
      }
    }

    // Check if any output is dirty
    bool any_output_dirty = false;
    for (auto* output : edge->outputs_) {
      if (output->dirty()) { any_output_dirty = true; break; }
    }

    if (!any_output_dirty && !edge->outputs_ready_) any_output_dirty = true;

    if (!any_output_dirty) {
      // All outputs are up to date
      for (auto* output : edge->outputs_) {
        output->set_dirty(false);
      }
    } else {
      // Mark all outputs as dirty
      for (auto* output : edge->outputs_) {
        output->set_dirty(true);
      }

      if (opts_.debug_explain && any_output_dirty) {
        // Find which output is dirty
        for (auto* output : edge->outputs_) {
          if (output->dirty()) {
            fprintf(stderr, "ninja explain: %s is dirty\n", output->path().c_str());
          }
        }
      }
    }

    edge->outputs_ready_ = !any_output_dirty;
    edge->mark_ = Edge::VISIT_DONE;
    in_stack.erase(node);

    return true;
  };

  for (auto* node : *nodes) {
    if (!Visit(node)) return false;
  }

  return true;
}

