Plan::Plan(DependencyScan* scan) : scan_(scan), wanted_edges_(0), command_edges_(0) {}

void Plan::Reset() {
  want_.clear();
  ready_.clear();
  wanted_edges_ = 0;
  command_edges_ = 0;
}

bool Plan::AddTarget(Node* node, std::string* err) {
  return AddSubTarget(node, nullptr, err, nullptr);
}

bool Plan::AddSubTarget(Node* node, Node* dependent, std::string* err,
                         std::set<Edge*>* dyndep_walk) {
  Edge* edge = node->in_edge();
  if (!edge) {
    // Source file
    if (!node->exists() && !node->dirty()) {
      std::string stat_err;
      if (!node->Stat(&stat_err)) {
        *err = stat_err;
        return false;
      }
      if (!node->exists()) {
        *err = "'" + node->path() + "', needed by '" + 
               (dependent ? dependent->path() : "unknown") + 
               "', missing and no known rule to make it";
        return false;
      }
    }
    return true;
  }

  if (edge->outputs_ready_) return true;  // Already up to date

  // Check if already in the plan
  auto it = want_.find(edge);
  bool want_edge = false;

  if (it == want_.end()) {
    // New edge - check if we want to build it
    bool should_build = false;
    for (auto* output : edge->outputs_) {
      if (output->dirty()) { should_build = true; break; }
    }

    want_edge = should_build;
    want_[edge] = want_edge;

    if (want_edge) {
      wanted_edges_++;
      if (!edge->IsPhony()) command_edges_++;
    }

    // Recurse into inputs
    for (auto* input : edge->inputs_) {
      if (!AddSubTarget(input, node, err, dyndep_walk)) return false;
    }
  }

  if (want_.count(edge) && want_[edge]) {
    // Check if edge is ready (all inputs built)
    bool ready = true;
    for (auto* input : edge->inputs_) {
      Edge* in_edge = input->in_edge();
      if (in_edge && want_.count(in_edge) && want_[in_edge]) {
        ready = false;
        break;
      }
    }

    if (ready) {
      // Check if already in ready list
      bool found = false;
      for (auto* e : ready_) {
        if (e == edge) { found = true; break; }
      }
      if (!found) ready_.push_back(edge);
    }
  }

  return true;
}

Edge* Plan::FindWork() {
  // Process pools - find first edge in ready_ that can run
  for (size_t i = 0; i < ready_.size(); i++) {
    Edge* edge = ready_[i];
    Pool* pool = edge->pool_;

    if (pool && pool->ShouldDelayEdge()) {
      pool->DelayEdge(edge);
      ready_.erase(ready_.begin() + i);
      i--;
      continue;
    }

    ready_.erase(ready_.begin() + i);
    if (pool) pool->EdgeScheduled(*edge);
    return edge;
  }
  return nullptr;
}

void Plan::EdgeFinished(Edge* edge, bool success, std::string* err) {
  Pool* pool = edge->pool_;
  if (pool) {
    pool->EdgeFinished(*edge);
    // Schedule delayed edges
    while (!pool->ShouldDelayEdge()) {
      Edge* delayed = pool->GetNextEdge();
      if (!delayed) break;
      ready_.push_back(delayed);
    }
  }

  want_[edge] = false;
  wanted_edges_--;
  if (!edge->IsPhony()) command_edges_--;

  if (!success) return;

  // Mark outputs as no longer dirty and update downstream
  for (auto* output : edge->outputs_) {
    // Refresh mtime
    std::string stat_err;
    output->Stat(&stat_err);
    output->set_dirty(false);

    // Check downstream edges
    for (auto* out_edge : output->out_edges_) {
      if (!want_.count(out_edge) || !want_[out_edge]) continue;

      // Check if out_edge is ready
      bool ready = true;
      for (auto* input : out_edge->inputs_) {
        Edge* in_edge = input->in_edge();
        if (in_edge && want_.count(in_edge) && want_[in_edge]) {
          ready = false;
          break;
        }
        if (input->dirty()) {
          ready = false;
          break;
        }
      }

      if (ready) {
        bool found = false;
        for (auto* e : ready_) {
          if (e == out_edge) { found = true; break; }
        }
        if (!found) ready_.push_back(out_edge);
      }
    }
  }
}

