BuildStatus::BuildStatus(const NinjaOptions& opts) 
    : opts_(opts), total_edges_(0), started_edges_(0), finished_edges_(0),
      running_edges_(0), start_time_millis_(0), 
      overall_rate_(0), current_rate_(0),
      last_update_millis_(0) {}

