std::string BuildStatus::FormatProgressStatus(const char* fmt, int64_t time_millis) const {
  std::string result;
  for (const char* p = fmt; *p; ++p) {
    if (*p == '%') {
      ++p;
      if (!*p) break;
      switch (*p) {
        case 's': {
          char buf[32];
          snprintf(buf, sizeof(buf), "%d", started_edges_);
          result += buf;
          break;
        }
        case 'f': {
          char buf[32];
          snprintf(buf, sizeof(buf), "%d", finished_edges_);
          result += buf;
          break;
        }
        case 't': {
          char buf[32];
          snprintf(buf, sizeof(buf), "%d", total_edges_);
          result += buf;
          break;
        }
        case 'r': {
          char buf[32];
          snprintf(buf, sizeof(buf), "%d", running_edges_);
          result += buf;
          break;
        }
        case 'u': {
          char buf[32];
          snprintf(buf, sizeof(buf), "%d", total_edges_ - started_edges_);
          result += buf;
          break;
        }
        case 'p': {
          char buf[32];
          int pct = total_edges_ > 0 ? (100 * finished_edges_) / total_edges_ : 0;
          snprintf(buf, sizeof(buf), "%d%%", pct);
          result += buf;
          break;
        }
        case 'P': {
          char buf[32];
          int pct = total_edges_ > 0 ? (100 * finished_edges_) / total_edges_ : 0;
          snprintf(buf, sizeof(buf), "%3d%%", pct);
          result += buf;
          break;
        }
        case 'o': {
          // Overall rate
          char buf[32];
          double elapsed = (time_millis - start_time_millis_) / 1000.0;
          double rate = elapsed > 0 ? finished_edges_ / elapsed : 0;
          if (rate >= 100 || rate == 0)
            snprintf(buf, sizeof(buf), "%.0f", rate);
          else
            snprintf(buf, sizeof(buf), "%.1f", rate);
          result += buf;
          break;
        }
        case 'c': {
          // Current rate
          char buf[32];
          if (current_rate_ >= 100 || current_rate_ == 0)
            snprintf(buf, sizeof(buf), "%.0f", current_rate_);
          else
            snprintf(buf, sizeof(buf), "%.1f", current_rate_);
          result += buf;
          break;
        }
        case 'e': {
          // Elapsed time in seconds
          char buf[32];
          double elapsed = (time_millis - start_time_millis_) / 1000.0;
          snprintf(buf, sizeof(buf), "%.3f", elapsed);
          result += buf;
          break;
        }
        case 'E': {
          // ETA
          char buf[32];
          double elapsed = (time_millis - start_time_millis_) / 1000.0;
          double rate = elapsed > 0 ? finished_edges_ / elapsed : 0;
          int remaining = total_edges_ - finished_edges_;
          if (rate > 0) {
            double eta = remaining / rate;
            snprintf(buf, sizeof(buf), "%.3f", eta);
          } else {
            snprintf(buf, sizeof(buf), "-");
          }
          result += buf;
          break;
        }
        case 'w': {
          // Elapsed time in [h:]mm:ss
          int64_t elapsed_ms = time_millis - start_time_millis_;
          int secs = (int)(elapsed_ms / 1000);
          int mins = secs / 60;
          secs %= 60;
          int hours = mins / 60;
          mins %= 60;
          char buf[32];
          if (hours > 0)
            snprintf(buf, sizeof(buf), "%d:%02d:%02d", hours, mins, secs);
          else
            snprintf(buf, sizeof(buf), "%d:%02d", mins, secs);
          result += buf;
          break;
        }
        case 'W': {
          // ETA in [h:]mm:ss
          double elapsed = (time_millis - start_time_millis_) / 1000.0;
          double rate = elapsed > 0 ? finished_edges_ / elapsed : 0;
          int remaining = total_edges_ - finished_edges_;
          char buf[32];
          if (rate > 0) {
            int secs = (int)(remaining / rate);
            int mins = secs / 60;
            secs %= 60;
            int hours = mins / 60;
            mins %= 60;
            if (hours > 0)
              snprintf(buf, sizeof(buf), "%d:%02d:%02d", hours, mins, secs);
            else
              snprintf(buf, sizeof(buf), "%d:%02d", mins, secs);
          } else {
            snprintf(buf, sizeof(buf), "-");
          }
          result += buf;
          break;
        }
        case '%':
          result += '%';
          break;
        default:
          result += '%';
          result += *p;
          break;
      }
    } else {
      result += *p;
    }
  }
  return result;
}

