void BuildStatus::PrintStatus(const Edge* edge, int64_t time_millis) {
  if (opts_.quiet) return;

  const char* default_fmt = "[%f/%t] ";
  const char* fmt = getenv("NINJA_STATUS");
  if (!fmt) fmt = default_fmt;

  std::string status = FormatProgressStatus(fmt, time_millis);

  std::string to_print;
  if (opts_.verbose) {
    to_print = edge->EvaluateCommand();
  } else {
    to_print = edge->GetDescription();
    if (to_print.empty()) to_print = edge->EvaluateCommand();
  }

  // Use \r to overwrite line if not verbose and output is a tty
  static bool is_tty = isatty(STDOUT_FILENO);

  printf("%s%s\n", status.c_str(), to_print.c_str());
  fflush(stdout);
}

void BuildStatus::BuildEdgeStarted(const Edge* edge, int64_t start_time) {
  ++started_edges_;
  ++running_edges_;

  if (edge->pool_ == &State::kConsolePool) {
    int64_t now = GetTimeMillis();
    PrintStatus(edge, now);
  }
}

void BuildStatus::BuildEdgeFinished(const Edge* edge, int64_t start_time, int64_t end_time,
                                     bool success, const std::string& output) {
  ++finished_edges_;
  --running_edges_;

  // Update current rate (simple exponential moving average)
  // Not a full rate tracker, but good enough

  if (edge->pool_ != &State::kConsolePool) {
    PrintStatus(edge, end_time);
  }

  if (!output.empty()) {
    // Print output from failed or verbose commands
    fflush(stdout);
    fprintf(stdout, "%s", output.c_str());
    if (output.back() != '\n') fprintf(stdout, "\n");
    fflush(stdout);
  }
}

