// Tool: deps
static int ToolDeps(State* state, const NinjaOptions& opts, const std::vector<const char*>& args) {
  DepsLog deps_log;
  std::string deps_path = ".ninja_deps";

  // Check for builddir
  std::string builddir = state->bindings_->LookupVariable("builddir");
  if (!builddir.empty()) {
    deps_path = builddir + "/.ninja_deps";
  }

  std::string err;
  if (!deps_log.Load(deps_path, state, &err)) {
    if (!err.empty()) {
      fprintf(stderr, "ninja: warning: loading '%s': %s\n", deps_path.c_str(), err.c_str());
    }
    return 1;
  }

  std::vector<Node*> nodes;
  if (args.empty()) {
    nodes = deps_log.nodes_;
  } else {
    for (auto* arg : args) {
      Node* node = state->LookupNode(arg);
      if (!node) {
        fprintf(stderr, "ninja: unknown target '%s'\n", arg);
        return 1;
      }
      nodes.push_back(node);
    }
  }

  for (auto* node : nodes) {
    if (!node) continue;
    DepsLog::Deps* deps = deps_log.GetDeps(node);
    if (!deps) continue;

    // Stat the node
    std::string stat_err;
    node->Stat(&stat_err);

    bool valid = (node->mtime() == deps->mtime);

    fprintf(stdout, "%s: #deps %d, deps mtime %" PRId64 " (%s)\n",
            node->path().c_str(), deps->node_count, deps->mtime,
            valid ? "VALID" : "STALE");

    for (int i = 0; i < deps->node_count; i++) {
      if (deps->nodes[i]) {
        fprintf(stdout, "    %s\n", deps->nodes[i]->path().c_str());
      }
    }
    fprintf(stdout, "\n");
  }

  return 0;
}

// Tool: clean
static int ToolClean(State* state, const NinjaOptions& opts, const std::vector<const char*>& args) {
  bool clean_rules = false;
  std::vector<const char*> targets;

  for (auto* arg : args) {
    if (strcmp(arg, "-r") == 0) {
      clean_rules = true;
    } else {
      targets.push_back(arg);
    }
  }

  Cleaner cleaner(state, opts);

  int result = 0;
  if (clean_rules) {
    if (targets.empty()) {
      fprintf(stderr, "expected a rule to clean\n");
      return 1;
    }
    for (auto* t : targets) {
      result = cleaner.CleanRule(t);
    }
  } else if (!targets.empty()) {
    for (auto* t : targets) {
      result = cleaner.CleanTarget(t);
    }
  } else {
    result = cleaner.CleanAll();
  }

  return result;
}

// Tool: cleandead
static int ToolCleandead(State* state, const NinjaOptions& opts, const std::vector<const char*>& args) {
  BuildLog build_log;
  std::string log_path = ".ninja_log";
  std::string builddir = state->bindings_->LookupVariable("builddir");
  if (!builddir.empty()) log_path = builddir + "/.ninja_log";

  std::string err;
  if (!build_log.Load(log_path, &err)) {
    fprintf(stderr, "ninja: warning: %s\n", err.c_str());
  }

  Cleaner cleaner(state, opts);
  return cleaner.CleanDead(build_log.entries_);
}

// Tool: recompact
static int ToolRecompact(State* state, const NinjaOptions& opts) {
  // Load and recompact build log
  std::string builddir = state->bindings_->LookupVariable("builddir");
  std::string log_path = ".ninja_log";
  std::string deps_path = ".ninja_deps";
  if (!builddir.empty()) {
    log_path = builddir + "/.ninja_log";
    deps_path = builddir + "/.ninja_deps";
  }

  {
    BuildLog build_log;
    std::string err;
    if (build_log.Load(log_path, &err)) {
      if (!build_log.Recompact(log_path, &err)) {
        fprintf(stderr, "ninja: error: %s\n", err.c_str());
        return 1;
      }
    }
  }

  {
    DepsLog deps_log;
    std::string err;
    if (deps_log.Load(deps_path, state, &err)) {
      if (!deps_log.Recompact(deps_path, *state, &err)) {
        fprintf(stderr, "ninja: error: %s\n", err.c_str());
        return 1;
      }
    }
  }

  return 0;
}

// Tool: restat
static int ToolRestat(State* state, const NinjaOptions& opts) {
  std::string builddir = state->bindings_->LookupVariable("builddir");
  std::string log_path = ".ninja_log";
  if (!builddir.empty()) log_path = builddir + "/.ninja_log";

  BuildLog build_log;
  std::string err;
  if (!build_log.Load(log_path, &err)) {
    fprintf(stderr, "ninja: warning: %s\n", err.c_str());
