// Tool: targets
static int ToolTargets(State* state, const std::vector<const char*>& args) {
  std::string mode = "default";
  if (!args.empty()) mode = args[0];

  if (mode == "all") {
    // List all targets
    for (auto& kv : state->paths_) {
      Node* node = kv.second;
      if (node->in_edge()) {
        fprintf(stdout, "%s: %s\n", node->path().c_str(), 
                node->in_edge()->rule_->name().c_str());
      }
    }
  } else if (mode == "rule" && args.size() >= 2) {
    // List targets by rule
    std::string rule_name = args[1];
    for (auto& kv : state->paths_) {
      Node* node = kv.second;
      if (node->in_edge() && node->in_edge()->rule_->name() == rule_name) {
        fprintf(stdout, "%s\n", node->path().c_str());
      }
    }
  } else if (mode == "depth" && args.size() >= 2) {
    int depth = atoi(args[1]);

    // BFS from default targets
    std::string err;
    std::vector<Node*> defaults = state->DefaultNodes(&err);

    struct QueueEntry {
      Node* node;
      int depth;
      int indent;
    };

    std::queue<QueueEntry> q;
    std::set<Node*> visited;

    for (auto* node : defaults) {
      q.push({node, 0, 0});
    }

    while (!q.empty()) {
      auto [node, d, indent] = q.front();
      q.pop();

      if (!node->in_edge()) continue;
      if (visited.count(node)) continue;
      visited.insert(node);

      std::string spaces(indent * 2, ' ');
      fprintf(stdout, "%s%s: %s\n", spaces.c_str(), 
              node->path().c_str(), node->in_edge()->rule_->name().c_str());

      if (d < depth) {
        for (auto* input : node->in_edge()->inputs_) {
          q.push({input, d + 1, indent + 1});
        }
      }
    }
  } else {
    // Default: list default targets
    std::string err;
    std::vector<Node*> defaults;

    if (!state->defaults_.empty()) {
      defaults = state->defaults_;
    } else {
      // Find "root" targets - nodes with no outgoing edges that have in_edge
      for (auto& kv : state->paths_) {
        Node* node = kv.second;
        if (node->in_edge() && node->out_edges_.empty()) {
          defaults.push_back(node);
        }
      }
    }

    for (auto* node : defaults) {
      if (node->in_edge()) {
        fprintf(stdout, "%s: %s\n", node->path().c_str(),
                node->in_edge()->rule_->name().c_str());
      }
    }
  }

  return 0;
}

// Tool: rules  
static int ToolRules(State* state, const std::vector<const char*>& args) {
  bool show_description = false;
  for (auto* arg : args) {
    if (strcmp(arg, "-d") == 0) show_description = true;
  }

  for (auto& kv : state->rules_) {
    const Rule* rule = kv.second;
    if (rule == &State::kPhonyRule && !show_description) {
      fprintf(stdout, "%s\n", rule->name().c_str());
      continue;
    }
    if (show_description) {
      const EvalString* desc = rule->GetBinding("description");
      if (desc) {
        fprintf(stdout, "%s: %s\n", rule->name().c_str(), desc->Unparse().c_str());
      } else {
        fprintf(stdout, "%s\n", rule->name().c_str());
      }
    } else {
      fprintf(stdout, "%s\n", rule->name().c_str());
    }
  }
  return 0;
}

// Tool: query
static int ToolQuery(State* state, const std::vector<const char*>& args) {
  if (args.empty()) {
    fprintf(stderr, "usage: ninja -t query TARGET...\n");
    return 1;
  }

  for (auto* arg : args) {
    Node* node = state->LookupNode(arg);
    if (!node) {
      fprintf(stderr, "ninja: unknown target '%s'\n", arg);
      return 1;
    }

    fprintf(stdout, "%s:\n", node->path().c_str());

    if (node->in_edge()) {
      Edge* edge = node->in_edge();
      fprintf(stdout, "  input: %s\n", edge->rule_->name().c_str());

      int explicit_in = (int)edge->inputs_.size() - edge->implicit_deps_ - edge->order_only_deps_;
      for (int i = 0; i < explicit_in; i++) {
        fprintf(stdout, "    %s\n", edge->inputs_[i]->path().c_str());
      }

      if (edge->implicit_deps_ > 0) {
        fprintf(stdout, "  implicit:\n");
        for (int i = explicit_in; i < explicit_in + edge->implicit_deps_; i++) {
          fprintf(stdout, "    %s\n", edge->inputs_[i]->path().c_str());
        }
      }

      if (edge->order_only_deps_ > 0) {
        fprintf(stdout, "  order-only:\n");
        for (int i = explicit_in + edge->implicit_deps_; i < (int)edge->inputs_.size(); i++) {
          fprintf(stdout, "    %s\n", edge->inputs_[i]->path().c_str());
        }
      }
    }

    // Output edges
    fprintf(stdout, "  outputs:\n");
    for (auto* out_edge : node->out_edges_) {
      for (auto* out : out_edge->outputs_) {
        fprintf(stdout, "    %s\n", out->path().c_str());
      }
    }
  }
  return 0;
}

// Tool: graph
static int ToolGraph(State* state, const std::vector<const char*>& args) {
  std::vector<Node*> nodes;

  if (args.empty()) {
    std::string err;
    nodes = state->DefaultNodes(&err);
    if (nodes.empty()) {
      fprintf(stderr, "ninja: error: %s\n", err.c_str());
      return 1;
    }
  } else {
    for (auto* arg : args) {
      Node* node = state->LookupNode(arg);
      if (!node) {
        fprintf(stderr, "ninja: unknown target '%s'\n", arg);
        return 1;
      }
      nodes.push_back(node);
    }
  }

  fprintf(stdout, "digraph ninja {\n");
  fprintf(stdout, "rankdir=\"LR\"\n");
  fprintf(stdout, "node [fontsize=10, shape=box, height=0.25]\n");
  fprintf(stdout, "edge [fontsize=10]\n");

  std::set<Edge*> visited;
  std::function<void(Node*)> Visit = [&](Node* node) {
    Edge* edge = node->in_edge();
    fprintf(stdout, "\"%p\" [label=\"%s\"]\n", node, node->path().c_str());

    if (!edge) return;
    if (visited.count(edge)) {
      fprintf(stdout, "\"%p\" -> \"%p\" [arrowhead=none]\n", edge, node);
      return;
    }
    visited.insert(edge);

    fprintf(stdout, "\"%p\" [label=\"%s\", shape=ellipse]\n", 
            edge, edge->rule_->name().c_str());
    fprintf(stdout, "\"%p\" -> \"%p\"\n", edge, node);

    for (auto* input : edge->inputs_) {
      fprintf(stdout, "\"%p\" -> \"%p\" [arrowhead=none]\n", input, edge);
      Visit(input);
    }
  };

  for (auto* node : nodes) {
    Edge* edge = node->in_edge();
    if (edge) {
      fprintf(stdout, "\"%p\" [label=\"%s\"]\n", node, node->path().c_str());
      fprintf(stdout, "\"%p\" [label=\"%s\", shape=ellipse]\n",
              edge, edge->rule_->name().c_str());
      fprintf(stdout, "\"%p\" -> \"%p\"\n", edge, node);

      std::set<Edge*> edge_visited;
      std::function<void(Edge*)> VisitEdge = [&](Edge* e) {
        if (edge_visited.count(e)) return;
        edge_visited.insert(e);

        for (auto* input : e->inputs_) {
          fprintf(stdout, "\"%p\" -> \"%p\" [arrowhead=none]\n", input, e);
          if (input->in_edge()) {
            fprintf(stdout, "\"%p\" [label=\"%s\"]\n", input, input->path().c_str());
            fprintf(stdout, "\"%p\" -> \"%p\" [label=\" %s\"]\n",
                    input, input->in_edge(), input->in_edge()->rule_->name().c_str());
            VisitEdge(input->in_edge());
          } else {
            fprintf(stdout, "\"%p\" [label=\"%s\"]\n", input, input->path().c_str());
          }
        }
      };
      VisitEdge(edge);
    } else {
      fprintf(stdout, "\"%p\" [label=\"%s\"]\n", node, node->path().c_str());
    }
  }

  fprintf(stdout, "}\n");
  return 0;
}

// Tool: commands
static int ToolCommands(State* state, const std::vector<const char*>& args) {
  std::vector<Node*> nodes;

  if (args.empty()) {
    std::string err;
    nodes = state->DefaultNodes(&err);
    if (nodes.empty()) {
      fprintf(stderr, "ninja: error: %s\n", err.c_str());
      return 1;
    }
  } else {
    for (auto* arg : args) {
      Node* node = state->LookupNode(arg);
      if (!node) {
        fprintf(stderr, "ninja: unknown target '%s'\n", arg);
        return 1;
      }
      nodes.push_back(node);
    }
  }

  // Collect commands in order
  std::set<Edge*> visited;
  std::vector<Edge*> ordered;

  std::function<void(Node*)> Visit = [&](Node* node) {
    Edge* edge = node->in_edge();
    if (!edge) return;
    if (visited.count(edge)) return;
    visited.insert(edge);

    for (auto* input : edge->inputs_) {
      Visit(input);
    }

    if (!edge->IsPhony()) {
      ordered.push_back(edge);
    }
  };

  for (auto* node : nodes) {
    Visit(node);
  }

  for (auto* edge : ordered) {
    fprintf(stdout, "%s\n", edge->EvaluateCommand().c_str());
  }

  return 0;
}

