                for (char c : cmd) {
                  if (c == '"') escaped += "\\\"";
                  else if (c == '\\') escaped += "\\\\";
                  else escaped += c;
                }
                return escaped;
              }().c_str());
      fprintf(stdout, "    \"file\": \"%s\",\n", input->path().c_str());
      fprintf(stdout, "    \"output\": \"%s\"\n", output.c_str());
      fprintf(stdout, "  }");
