    if (build_log.Load(log_path, &err)) {
      if (!build_log.Recompact(log_path, &err)) {
        fprintf(stderr, "ninja: error: %s\n", err.c_str());
        return 1;
      }
    }
  }

  {
    DepsLog deps_log;
    std::string err;
    if (deps_log.Load(deps_path, state, &err)) {
      if (!deps_log.Recompact(deps_path, *state, &err)) {
        fprintf(stderr, "ninja: error: %s\n", err.c_str());
        return 1;
      }
    }
  }

  return 0;
}

// Tool: restat
static int ToolRestat(State* state, const NinjaOptions& opts) {
  std::string builddir = state->bindings_->LookupVariable("builddir");
  std::string log_path = ".ninja_log";
  if (!builddir.empty()) log_path = builddir + "/.ninja_log";

  BuildLog build_log;
  std::string err;
  if (!build_log.Load(log_path, &err)) {
    fprintf(stderr, "ninja: warning: %s\n", err.c_str());
  }

  if (!build_log.Restat(log_path, *state, &err)) {
    fprintf(stderr, "ninja: error: %s\n", err.c_str());
    return 1;
  }

  return 0;
}

