// Helper to collect all transitive inputs of a node
static void CollectInputs(Node* node, std::set<Node*>* visited, std::vector<Node*>* result) {
  Edge* edge = node->in_edge();
  if (!edge) return;

  for (auto* input : edge->inputs_) {
    if (visited->insert(input).second) {
      result->push_back(input);
      CollectInputs(input, visited, result);
    }
  }
}

// Tool: list
static int ToolList(State* state, const NinjaOptions& opts) {
