  std::string log_path = ".ninja_log";
  std::string builddir = state->bindings_->LookupVariable("builddir");
  if (!builddir.empty()) log_path = builddir + "/.ninja_log";

  std::string err;
  if (!build_log.Load(log_path, &err)) {
    fprintf(stderr, "ninja: warning: %s\n", err.c_str());
  }

  Cleaner cleaner(state, opts);
  return cleaner.CleanDead(build_log.entries_);
