// Tool: recompact
static int ToolRecompact(State* state, const NinjaOptions& opts) {
  // Load and recompact build log
  std::string builddir = state->bindings_->LookupVariable("builddir");
  std::string log_path = ".ninja_log";
  std::string deps_path = ".ninja_deps";
  if (!builddir.empty()) {
    log_path = builddir + "/.ninja_log";
    deps_path = builddir + "/.ninja_deps";
  }

  {
    BuildLog build_log;
    std::string err;
    if (build_log.Load(log_path, &err)) {
      if (!build_log.Recompact(log_path, &err)) {
        fprintf(stderr, "ninja: error: %s\n", err.c_str());
        return 1;
      }
    }
  }

  {
    DepsLog deps_log;
    std::string err;
    if (deps_log.Load(deps_path, state, &err)) {
