      if (!depfile.empty()) Remove(depfile);
    }

    for (auto* input : edge->inputs_) {
      Visit(input);
    }
  };

  Visit(node);

  fprintf(stdout, "Cleaning... %d files.\n", cleaned_files_count_);
  return 0;
}

int Cleaner::CleanDead(const std::map<std::string, struct BuildLog::LogEntry*>& entries) {
  cleaned_files_count_ = 0;
  removed_.clear();

  // Find all outputs currently in the build file
  std::set<std::string> current_outputs;
  for (auto* edge : state_->edges_) {
    for (auto* out : edge->outputs_) {
      current_outputs.insert(out->path());
    }
  }

  // Remove anything in the log that's not in current outputs
  for (auto& kv : entries) {
    if (!current_outputs.count(kv.first)) {
      Remove(kv.first);
    }
  }

  fprintf(stdout, "Cleaning... %d files.\n", cleaned_files_count_);
  return 0;
}
