#include "ninja.h"
#include "state.h"
#include "manifest_parser.h"
#include "build.h"
#include "build_log.h"
#include "deps_log.h"
#include "clean.h"
#include "subtools.h"
#include "util.h"
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <limits.h>
#include <vector>
#include <string>

const char* kNinjaVersion = "1.14.0.git";

static void Usage() {
  fprintf(stderr,
"usage: ninja [options] [targets...]\n"
"\n"
"if targets are unspecified, builds the 'default' target (see manual).\n"
"\n"
"options:\n"
"  --version      print ninja version (\"%s\")\n"
"  -v, --verbose  show all command lines while building\n"
"  --quiet        don't show progress status, just command output\n"
"\n"
"  -C DIR   change to DIR before doing anything else\n"
"  -f FILE  specify input build file [default=build.ninja]\n"
"\n"
"  -j N     run N jobs in parallel (0 means infinity) [default=%d on this system]\n"
"  -k N     keep going until N jobs fail (0 means infinity) [default=1]\n"
"  -l N     do not start new jobs if the load average is greater than N\n"
"  -n       dry run (don't run commands but act like they succeeded)\n"
"\n"
"  -d MODE  enable debugging (use '-d list' to list modes)\n"
"  -t TOOL  run a subtool (use '-t list' to list subtools)\n"
"    terminates toplevel options; further flags are passed to the tool\n"
"  -w FLAG  adjust warnings (use '-w list' to list warnings)\n",
          kNinjaVersion,
          GetParallelism());
}

int main(int argc, char* argv[]) {
  NinjaOptions opts;
  opts.input_file = "build.ninja";
  opts.parallelism = GetParallelism();
  opts.failures_allowed = 1;

  const char* tool_name = nullptr;
  std::vector<const char*> tool_args;

  int i = 1;
  for (; i < argc; ++i) {
    const char* arg = argv[i];

    if (strcmp(arg, "--version") == 0) {
      printf("%s\n", kNinjaVersion);
      return 0;
    } else if (strcmp(arg, "-v") == 0 || strcmp(arg, "--verbose") == 0) {
      opts.verbose = true;
    } else if (strcmp(arg, "--quiet") == 0) {
      opts.quiet = true;
    } else if (strcmp(arg, "-n") == 0) {
      opts.dry_run = true;
    } else if (strcmp(arg, "-h") == 0 || strcmp(arg, "--help") == 0) {
      Usage();
      return 1;
    } else if (strcmp(arg, "-C") == 0) {
      if (i + 1 >= argc) {
        fprintf(stderr, "ninja: error: -C requires an argument\n");
        return 1;
      }
      opts.dir = argv[++i];
    } else if (strncmp(arg, "-C", 2) == 0 && arg[2]) {
      opts.dir = arg + 2;
    } else if (strcmp(arg, "-f") == 0) {
      if (i + 1 >= argc) {
        fprintf(stderr, "ninja: error: -f requires an argument\n");
        return 1;
      }
      opts.input_file = argv[++i];
    } else if (strncmp(arg, "-f", 2) == 0 && arg[2]) {
      opts.input_file = arg + 2;
    } else if (strcmp(arg, "-j") == 0) {
      if (i + 1 >= argc) {
        fprintf(stderr, "ninja: error: -j requires an argument\n");
        return 1;
      }
      int j = atoi(argv[++i]);
      if (j < 0) {
        fprintf(stderr, "ninja: error: invalid -j parameter\n");
        return 1;
      }
      opts.parallelism = j;
    } else if (strncmp(arg, "-j", 2) == 0 && arg[2]) {
      int j = atoi(arg + 2);
      if (j < 0) {
        fprintf(stderr, "ninja: error: invalid -j parameter\n");
        return 1;
      }
      opts.parallelism = j;
    } else if (strcmp(arg, "-k") == 0) {
      if (i + 1 >= argc) {
        fprintf(stderr, "ninja: error: -k requires an argument\n");
        return 1;
      }
      opts.failures_allowed = atoi(argv[++i]);
    } else if (strncmp(arg, "-k", 2) == 0 && arg[2]) {
      opts.failures_allowed = atoi(arg + 2);
    } else if (strcmp(arg, "-l") == 0) {
      if (i + 1 >= argc) {
        fprintf(stderr, "ninja: error: -l requires an argument\n");
        return 1;
      }
      opts.max_load_average = (float)atof(argv[++i]);
    } else if (strncmp(arg, "-l", 2) == 0 && arg[2]) {
      opts.max_load_average = (float)atof(arg + 2);
    } else if (strcmp(arg, "-d") == 0) {
      if (i + 1 >= argc) {
        fprintf(stderr, "ninja: error: -d requires an argument\n");
        return 1;
      }
      if (!opts.SetDebugMode(argv[++i])) {
        return 1;
      }
    } else if (strncmp(arg, "-d", 2) == 0 && arg[2]) {
      if (!opts.SetDebugMode(arg + 2)) {
        return 1;
      }
    } else if (strcmp(arg, "-t") == 0) {
      if (i + 1 >= argc) {
        fprintf(stderr, "ninja: error: -t requires an argument\n");
        return 1;
      }
      tool_name = argv[++i];
      for (++i; i < argc; ++i)
        tool_args.push_back(argv[i]);
      break;
    } else if (strncmp(arg, "-t", 2) == 0 && arg[2]) {
      tool_name = arg + 2;
      for (++i; i < argc; ++i)
        tool_args.push_back(argv[i]);
      break;
    } else if (strcmp(arg, "-w") == 0) {
      if (i + 1 >= argc) {
        fprintf(stderr, "ninja: error: -w requires an argument\n");
        return 1;
      }
      if (!opts.SetWarningMode(argv[++i])) {
        return 1;
      }
    } else if (strncmp(arg, "-w", 2) == 0 && arg[2]) {
      if (!opts.SetWarningMode(arg + 2)) {
        return 1;
      }
    } else if (arg[0] == '-') {
      fprintf(stderr, "ninja: error: unknown flag '%s'\n", arg);
      Usage();
      return 1;
    } else {
      opts.targets.push_back(arg);
    }
  }

  // Change directory if requested
  if (!opts.dir.empty()) {
    if (chdir(opts.dir.c_str()) < 0) {
      fprintf(stderr, "ninja: error: chdir('%s') - %s\n",
              opts.dir.c_str(), strerror(errno));
      return 1;
    }
  }

  // Handle tool
  if (tool_name) {
    // Special case: -t list doesn't need state
    if (strcmp(tool_name, "list") == 0) {
      return RunTool(tool_name, tool_args, nullptr, opts);
    }

    // Load build file
    State state;
    ManifestParser parser(&state, opts);
    std::string err;
    if (!parser.Load(opts.input_file, &err)) {
      fprintf(stderr, "ninja: error: %s\n", err.c_str());
      return 1;
    }

    return RunTool(tool_name, tool_args, &state, opts);
  }

  // Normal build
  return RunBuild(opts);
}
