// Cleans build outputs
struct Cleaner {
  Cleaner(State* state, const NinjaOptions& opts);

  int CleanAll();
  int CleanRule(const char* rule_name);
  int CleanTarget(const char* target);

  template<typename T>
  int CleanDead(const T& entries) {
    cleaned_files_count_ = 0;
    removed_.clear();

    // Find all outputs currently in the build file
    std::set<std::string> current_outputs;
    for (auto* edge : state_->edges_) {
      for (auto* out : edge->outputs_) {
        current_outputs.insert(out->path());
      }
    }

    // Remove anything in the log that's not in current outputs
    for (auto& kv : entries) {
      if (!current_outputs.count(kv.first)) {
        Remove(kv.first);
      }
    }

    fprintf(stdout, "Cleaning... %d files.\n", cleaned_files_count_);
    return 0;
  }

  int cleaned_files_count_;

private:
  void Remove(const std::string& path);
  void PrintIfVerbose(const std::string& path) const;

  State* state_;
  const NinjaOptions& opts_;
  std::set<std::string> removed_;
};
