  removed_.insert(path);

  if (opts_.dry_run) {
    PrintIfVerbose(path);
    cleaned_files_count_++;
    return;
  }

  if (unlink(path.c_str()) == 0) {
    PrintIfVerbose(path);
    cleaned_files_count_++;
  } else if (errno != ENOENT) {
    fprintf(stderr, "ninja: warning: failed to remove '%s': %s\n",
            path.c_str(), strerror(errno));
  }
}

int Cleaner::CleanAll() {
  cleaned_files_count_ = 0;
  removed_.clear();

  for (auto* edge : state_->edges_) {
    if (edge->IsPhony()) continue;
    if (edge->GetBindingBool("generator")) continue;

    for (auto* output : edge->outputs_) {
      Remove(output->path());
    }

    std::string depfile = edge->GetBinding("depfile");
    if (!depfile.empty()) Remove(depfile);

    std::string rspfile = edge->GetBinding("rspfile");
    if (!rspfile.empty()) Remove(rspfile);
  }

  if (!opts_.dry_run) {
    fprintf(stdout, "Cleaning... %d files.\n", cleaned_files_count_);
  } else {
    fprintf(stdout, "Would clean %d files.\n", cleaned_files_count_);
  }

  return 0;
}

int Cleaner::CleanRule(const char* rule_name) {
  cleaned_files_count_ = 0;
  removed_.clear();

  for (auto* edge : state_->edges_) {
    if (edge->rule_->name() != rule_name) continue;
    if (edge->IsPhony()) continue;

    for (auto* output : edge->outputs_) {
      Remove(output->path());
    }

    std::string depfile = edge->GetBinding("depfile");
    if (!depfile.empty()) Remove(depfile);
  }

  fprintf(stdout, "Cleaning... %d files.\n", cleaned_files_count_);
  return 0;
}

int Cleaner::CleanTarget(const char* target) {
  cleaned_files_count_ = 0;
  removed_.clear();

  Node* node = state_->LookupNode(target);
  if (!node) {
    fprintf(stderr, "ninja: error: unknown target '%s'\n", target);
    return 1;
  }

  std::set<Edge*> visited;
  std::function<void(Node*)> Visit = [&](Node* n) {
    Edge* edge = n->in_edge();
    if (!edge) return;
    if (visited.count(edge)) return;
    visited.insert(edge);

    if (!edge->IsPhony() && !edge->GetBindingBool("generator")) {
      for (auto* out : edge->outputs_) {
        Remove(out->path());
      }
      std::string depfile = edge->GetBinding("depfile");
      if (!depfile.empty()) Remove(depfile);
    }

    for (auto* input : edge->inputs_) {
      Visit(input);
    }
  };

  Visit(node);

  fprintf(stdout, "Cleaning... %d files.\n", cleaned_files_count_);
  return 0;
}
