# AH HA! Found the bug! In FinishEdge, when success=false:
# - We print output (if any)
# - Call plan_.EdgeFinished
# - RETURN TRUE (early return!)
# We NEVER call BuildEdgeFinished for failed edges!
#
# This means:
# 1. For failed bad.txt: FinishEdge returns early WITHOUT calling BuildEdgeFinished
# 2. So PrintStatus is never called for bad.txt
# 3. Back in Builder::Build: we print "FAILED: ..."
# 4. Then good.txt finishes: FinishEdge (success=true) calls BuildEdgeFinished -> prints status
#
# The fix: call BuildEdgeFinished for ALL edges (success or not) in FinishEdge.
# But we need to call it BEFORE printing "FAILED:" info.

python3 << 'EOF'
with open('/workspace/src/build.cc', 'r') as f:
    content = f.read()

old = '''  if (!success) {
    // Print output for failed commands
    if (!output.empty()) {
      fprintf(stdout, "%s", output.c_str());
      if (!output.empty() && output.back() != '\\n') fprintf(stdout, "\\n");
      fflush(stdout);
    }
    plan_.EdgeFinished(edge, success, err);
    return true;
  }'''

new = '''  if (!success) {
    // Print status line for failed command (before FAILED: message)
    status_->BuildEdgeFinished(edge, start_time, end_time, success, "");
    // Print output from failed command
    if (!output.empty()) {
      fprintf(stdout, "%s", output.c_str());
      if (!output.empty() && output.back() != '\\n') fprintf(stdout, "\\n");
      fflush(stdout);
    }
    plan_.EdgeFinished(edge, success, err);
    return true;
  }'''

content = content.replace(old, new)

with open('/workspace/src/build.cc', 'w') as f:
    f.write(content)
print("Fixed FinishEdge for failed commands")
EOF

