static int ToolMissingDeps(State* state, const NinjaOptions& opts, const std::vector<const char*>& args) {
  // Find targets that depend on generated files without proper deps
  // This is a best-effort implementation

  DepsLog deps_log;
  std::string deps_path = ".ninja_deps";
  std::string builddir = state->bindings_->LookupVariable("builddir");
  if (!builddir.empty()) deps_path = builddir + "/.ninja_deps";

  std::string err;
  deps_log.Load(deps_path, state, &err);

  // Find all generated (non-source) files
  std::set<Node*> generated;
  for (auto* edge : state->edges_) {
    if (edge->IsPhony()) continue;
    for (auto* out : edge->outputs_) {
      generated.insert(out);
    }
  }

  // Find targets that implicitly depend on generated files
  // but don't have explicit deps paths
  for (auto* edge : state->edges_) {
    if (edge->IsPhony()) continue;

    // Get deps from deps log
    for (auto* out : edge->outputs_) {
      DepsLog::Deps* deps = deps_log.GetDeps(out);
      if (!deps) continue;

      for (int i = 0; i < deps->node_count; i++) {
        Node* dep = deps->nodes[i];
        if (!dep) continue;
        if (!generated.count(dep)) continue;

        // This output depends on a generated file via deps
        // Check if there's an explicit path
        bool has_path = false;
        for (auto* input : edge->inputs_) {
          if (input == dep) { has_path = true; break; }
          // Check transitive
        }

        if (!has_path) {
          fprintf(stdout, "%s\\n", out->path().c_str());
          break;
        }
      }
    }
  }

  return 0;
}'''

